#[derive(Debug, Clone, Copy)]
struct CSharpNullableContextCase {
    name: &'static str,
    grammar_id: &'static str,
    context_owner_rule: &'static str,
    context_owner_field: &'static str,
    route_input: fn() -> (GrammarIr, GrammarStructuralModelSidecar),
}

#[derive(Debug, PartialEq, Eq)]
struct CSharpNullableSharedStructuralProfile {
    nullable_element_target_rule: String,
    nullable_question_node_kind: String,
    nullable_question_payload_kind: String,
    nullable_question_codec: String,
    token_range_roles: BTreeSet<String>,
}

#[test]
fn csharp_nullable_contexts_have_equivalent_structural_model_shape() {
    let cases = [
        CSharpNullableContextCase {
            name: "nullable_return_type",
            grammar_id: "csharp_local_nullable_return_type_syntax_v0",
            context_owner_rule: "MethodDeclarationSyntax",
            context_owner_field: "ReturnType",
            route_input: csharp_local_nullable_return_type_route_input,
        },
        CSharpNullableContextCase {
            name: "nullable_local_declaration",
            grammar_id: "csharp_local_nullable_declaration_syntax_v0",
            context_owner_rule: "VariableDeclarationSyntax",
            context_owner_field: "Type",
            route_input: csharp_local_nullable_declaration_route_input,
        },
        CSharpNullableContextCase {
            name: "nullable_property_declaration",
            grammar_id: "csharp_nullable_property_declaration_syntax_v0",
            context_owner_rule: "PropertyDeclarationSyntax",
            context_owner_field: "Type",
            route_input: csharp_nullable_property_declaration_route_input,
        },
        CSharpNullableContextCase {
            name: "nullable_parameter_declaration",
            grammar_id: "csharp_nullable_parameter_declaration_syntax_v0",
            context_owner_rule: "ParameterSyntax",
            context_owner_field: "Type",
            route_input: csharp_nullable_parameter_declaration_route_input,
        },
    ];

    let mut shared_profile = None;
    for case in cases {
        let (grammar, sidecar) = (case.route_input)();
        assert_eq!(grammar.grammar_id, case.grammar_id, "{} drifted", case.name);
        assert_eq!(
            sidecar.input.grammar_id, case.grammar_id,
            "{} sidecar input drifted",
            case.name
        );
        assert_eq!(sidecar.model_version, "structural-model-v0");
        assert!(sidecar.proof.tokenizable_decisions_match);
        assert!(sidecar.proof.checks["decision_graph_token_ranges_known"]);
        assert!(sidecar.proof.checks["decision_graph_payloads_match_payload_terminals"]);
        assert_eq!(
            sidecar.structural_model.boundary.role,
            "sidecar_evidence_only"
        );
        assert!(
            !sidecar
                .structural_model
                .boundary
                .generated_json_schema_output_changed
        );
        assert!(!sidecar.structural_model.boundary.core_compiler_path_changed);
        assert!(
            !sidecar
                .structural_model
                .boundary
                .production_grammar_compiler_path_changed
        );
        assert_csharp_nullable_context_reference(&sidecar, case);

        let profile = csharp_nullable_shared_structural_profile(&sidecar);
        if let Some(expected) = &shared_profile {
            assert_eq!(
                &profile, expected,
                "{} nullable shared StructuralModel profile drifted",
                case.name
            );
        } else {
            shared_profile = Some(profile);
        }
    }
}

fn assert_csharp_nullable_context_reference(
    sidecar: &GrammarStructuralModelSidecar,
    case: CSharpNullableContextCase,
) {
    assert!(
        sidecar.structural_model.references.iter().any(|reference| {
            reference.owner_rule == case.context_owner_rule
                && reference.field == case.context_owner_field
                && reference.target_rule == "NullableTypeSyntax"
                && reference.target_node_kind == "NullableTypeSyntax"
        }),
        "{} must preserve {}.{} -> NullableTypeSyntax",
        case.name,
        case.context_owner_rule,
        case.context_owner_field
    );
}

fn csharp_nullable_shared_structural_profile(
    sidecar: &GrammarStructuralModelSidecar,
) -> CSharpNullableSharedStructuralProfile {
    let nullable_element_reference = sidecar
        .structural_model
        .references
        .iter()
        .find(|reference| {
            reference.owner_rule == "NullableTypeSyntax"
                && reference.field == "ElementType"
                && reference.target_node_kind == "PredefinedTypeSyntax"
        })
        .unwrap_or_else(|| {
            panic!(
                "{} is missing NullableTypeSyntax.ElementType reference",
                sidecar.input.grammar_id
            )
        });
    let nullable_question_payload = sidecar
        .structural_model
        .payload_leaves
        .iter()
        .find(|payload| {
            payload.owner_rule == "NullableTypeSyntax" && payload.field == "QuestionToken"
        })
        .unwrap_or_else(|| {
            panic!(
                "{} is missing NullableTypeSyntax.QuestionToken payload leaf",
                sidecar.input.grammar_id
            )
        });

    CSharpNullableSharedStructuralProfile {
        nullable_element_target_rule: nullable_element_reference.target_rule.clone(),
        nullable_question_node_kind: nullable_question_payload.node_kind.clone(),
        nullable_question_payload_kind: nullable_question_payload.payload_kind.clone(),
        nullable_question_codec: nullable_question_payload.codec.clone(),
        token_range_roles: sidecar
            .structural_model
            .token_ranges
            .ranges
            .iter()
            .map(|range| range.role.clone())
            .collect(),
    }
}

