#[test]
fn syntax_backend_production_generator_api_boundary_consumes_contract_fixture() {
    let contract = load_contract();
    let boundary = contract
        .production_generator_api_boundary()
        .expect("production generator API boundary should accept fixture");

    assert_eq!(boundary.artifact_kind, ARTIFACT_KIND);
    assert_eq!(boundary.api_version, API_VERSION);
    assert_eq!(
        boundary.source_contract.boundary_manifest.path,
        BOUNDARY_MANIFEST_PATH
    );
    assert_eq!(
        boundary.source_contract.completed_promotion_class,
        "syntax backend production generator API boundary"
    );
    assert!(boundary.compiler_boundary.sidecar_only);
    assert!(!boundary.compiler_boundary.tct_compiler_route_allowed);
    assert!(
        !boundary
            .compiler_boundary
            .generated_json_schema_output_changed
    );
    assert!(!boundary.compiler_boundary.core_compiler_path_changed);
    assert!(
        !boundary
            .compiler_boundary
            .production_grammar_compiler_path_changed
    );
    assert!(
        boundary
            .compiler_boundary
            .preserves_json_schema_backend_contract
    );

    let input_surfaces = boundary
        .inputs
        .iter()
        .flat_map(|surface| surface.surfaces.iter().map(String::as_str))
        .collect::<BTreeSet<_>>();
    assert_eq!(
        input_surfaces,
        BTreeSet::from([
            "checked_syntax_input",
            "structural_model_boundary",
            "token_layout",
        ])
    );

    let output_surfaces = boundary
        .outputs
        .iter()
        .flat_map(|surface| surface.surfaces.iter().map(String::as_str))
        .collect::<BTreeSet<_>>();
    for surface in [
        "generated_codec_artifact_metadata",
        "strict_recovery_decode_policy",
        "consumed_token_accounting",
        "validation_hooks",
        "audit_markers",
        "maintained_documentation",
    ] {
        assert!(
            output_surfaces.contains(surface),
            "missing production generator output surface {surface}"
        );
    }

    for field in [
        "generated_crate_identity",
        "rendered_source_sha256",
        "target_manifest_sha256",
        "generation_options_sha256",
    ] {
        assert!(
            boundary
                .metadata_envelope
                .required_fields
                .iter()
                .any(|required| required == field),
            "missing metadata envelope field {field}"
        );
    }

    assert!(boundary.error_surface.strict_decode_authoritative);
    assert!(boundary.error_surface.recovery_normalizes_trailing_pad_only);
    assert!(boundary.error_surface.partial_prefix_failures_are_hard);
    assert!(boundary.error_surface.consumed_token_accounting_required);
    assert!(
        boundary
            .non_goals
            .iter()
            .any(|non_goal| non_goal.contains("TctCompiler"))
    );
    assert_eq!(
        boundary.next_missing_stable_promotion_class,
        NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
}

