#[test]
fn syntax_backend_validation_hook_sidecar_evidence_fixture_matches_contract() {
    let envelope = load_envelope();
    let contract = load_validation_hook_contract();
    contract
        .validate_against_artifact_envelope(&envelope)
        .expect("validation hook contract fixture should match artifact envelope");
    let evidence = load_validation_hook_sidecar_evidence();

    evidence
        .validate_against_contract(&contract)
        .expect("validation hook sidecar evidence fixture should match contract");

    assert_eq!(
        VALIDATION_HOOK_SIDECAR_EVIDENCE_FIXTURE_PATH,
        VALIDATION_HOOK_SIDECAR_EVIDENCE_PATH
    );
    assert_eq!(
        evidence.artifact_kind,
        VALIDATION_HOOK_SIDECAR_EVIDENCE_ARTIFACT_KIND
    );
    assert_eq!(
        evidence.source_validation_hook_contract.fixture_path,
        VALIDATION_HOOK_FIXTURE_PATH
    );
    assert_eq!(
        evidence.target_ids,
        vec!["toy".to_string(), "csharp".to_string(), "go".to_string()]
    );
    assert_eq!(evidence.records.len(), 3);
    assert!(evidence.sidecar_status.sidecar_only);
    assert!(!evidence.sidecar_status.stable_gate_promoted);
    assert!(!evidence.sidecar_status.live_toolchain_required);
    assert!(
        !evidence
            .sidecar_status
            .generated_hot_path_external_checks_allowed
    );
    assert!(evidence.compiler_boundary.sidecar_only);
    assert!(!evidence.compiler_boundary.tct_compiler_route_allowed);
    assert_eq!(
        evidence.next_missing_stable_promotion_class,
        VALIDATION_HOOK_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );

    let toy = evidence
        .records
        .iter()
        .find(|record| record.target_id == "toy")
        .expect("sidecar evidence should include toy target");
    assert_eq!(toy.parser_or_grammar_identity.kind, "grammar");
    assert_eq!(
        toy.parser_or_grammar_identity.grammar_id.as_deref(),
        Some("toy_assignment_v1")
    );
    assert_eq!(
        toy.sidecar_command_identity.check_kind,
        "source_parse_render_equivalence"
    );

    for parser_target in ["csharp", "go"] {
        let record = evidence
            .records
            .iter()
            .find(|record| record.target_id == parser_target)
            .unwrap_or_else(|| panic!("sidecar evidence should include {parser_target}"));
        assert_eq!(record.parser_or_grammar_identity.kind, "parser");
        assert!(record.parser_or_grammar_identity.tool.is_some());
        assert!(record.parser_or_grammar_identity.version.is_some());
        assert!(record.parser_or_grammar_identity.package.is_some());
        assert!(record.parser_or_grammar_identity.package_version.is_some());
        assert_eq!(
            record.sidecar_command_identity.check_kind,
            "parser_metadata_reproduction"
        );
        assert!(!record.sidecar_command_identity.live_toolchain_required);
        assert!(record.sidecar_command_identity.self_test_supported);
        assert_eq!(
            record.external_check_policy_sha256.len(),
            64,
            "external policy hash must be recorded for {parser_target}"
        );
        assert_eq!(
            record.validation_hook_contract_sha256.len(),
            64,
            "contract hash must be recorded for {parser_target}"
        );
        assert_eq!(record.sidecar_boundary.role, "sidecar_evidence_only");
        assert!(!record.sidecar_boundary.generated_json_schema_output_changed);
    }
}

