#[test]
fn syntax_backend_generated_artifact_replay_fixture_matches_sources() {
    let envelope = load_envelope();
    let validation_hook_contract = load_validation_hook_contract();
    validation_hook_contract
        .validate_against_artifact_envelope(&envelope)
        .expect("validation hook contract fixture should match artifact envelope");
    let sidecar_evidence = load_validation_hook_sidecar_evidence();
    sidecar_evidence
        .validate_against_contract(&validation_hook_contract)
        .expect("validation hook sidecar evidence fixture should match contract");
    let diagnostics_contract = load_input_diagnostics_contract();
    diagnostics_contract
        .validate_against_validation_hook_contract(&validation_hook_contract)
        .expect("input diagnostics contract fixture should match validation hook contract");
    let negative_fixture = load_input_diagnostics_negative_fixture();
    negative_fixture
        .validate_against_contract(&diagnostics_contract)
        .expect("input diagnostics negative fixture should match diagnostics contract");
    let replay = load_generated_artifact_replay();

    replay
        .validate_against_sources(
            &envelope,
            &sidecar_evidence,
            &diagnostics_contract,
            &negative_fixture,
        )
        .expect("generated artifact replay fixture should match source sidecar contracts");

    assert_eq!(
        GENERATED_ARTIFACT_REPLAY_FIXTURE_PATH,
        "tests/fixtures/syntax_backend/generated-artifact-replay-v1.json"
    );
    assert_eq!(
        replay.artifact_kind,
        GENERATED_ARTIFACT_REPLAY_ARTIFACT_KIND
    );
    assert_eq!(
        replay.source_generated_artifact_envelope.fixture_path,
        ENVELOPE_FIXTURE_PATH
    );
    assert_eq!(
        replay.source_validation_hook_sidecar_evidence.fixture_path,
        VALIDATION_HOOK_SIDECAR_EVIDENCE_PATH
    );
    assert_eq!(
        replay
            .source_input_diagnostics_negative_fixture
            .fixture_path,
        INPUT_DIAGNOSTICS_NEGATIVE_FIXTURE_PATH
    );
    assert_eq!(
        replay.target_ids,
        vec!["toy".to_string(), "csharp".to_string(), "go".to_string()]
    );
    assert_eq!(replay.records.len(), 3);
    assert!(!replay.volatile_report_policy.checked_in_reports);
    assert!(
        replay
            .deterministic_hash_fields
            .iter()
            .any(|field| field == "generated_artifact_envelope_sha256")
    );
    assert!(
        replay
            .deterministic_hash_fields
            .iter()
            .any(|field| field == "validation_hook_sidecar_evidence_sha256")
    );
    let csharp = replay
        .records
        .iter()
        .find(|record| record.target_id == "csharp")
        .expect("replay fixture should include C# parser-backed target");
    assert_eq!(csharp.source_kind, "tree_sitter");
    assert_eq!(csharp.parser_or_grammar_identity.kind, "parser");
    assert!(csharp.compiler_boundary_status.sidecar_artifact_only);
    assert!(!csharp.compiler_boundary_status.stable_tct_backend_route);
    assert!(replay.compiler_boundary.sidecar_only);
    assert!(!replay.compiler_boundary.tct_compiler_route_allowed);
    assert_eq!(
        replay.next_missing_stable_promotion_class,
        GENERATED_ARTIFACT_REPLAY_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
}

