#[test]
fn syntax_backend_tct_compiler_routing_gate_matches_generator_api() {
    let api_boundary = load_contract()
        .production_generator_api_boundary()
        .expect("production generator API boundary should accept fixture");
    let routing_gate = load_tct_compiler_routing_gate();

    routing_gate
        .validate_against_generator_api(&api_boundary)
        .expect("TctCompiler routing gate fixture should match generator API boundary");

    assert_eq!(
        routing_gate.artifact_kind,
        TCT_COMPILER_ROUTING_ARTIFACT_KIND
    );
    assert_eq!(
        routing_gate.source_renderer_api.module_path,
        "src/syntax_generated_codec.rs"
    );
    assert_eq!(
        routing_gate.routing_handoff.accepted_input,
        "checked GrammarIR -> StructuralModel"
    );
    assert_eq!(
        routing_gate.routing_handoff.output_artifact,
        "SyntaxGeneratedCodecArtifact"
    );
    assert!(!routing_gate.tct_compiler_route.route_registered);
    assert!(!routing_gate.tct_compiler_route.route_enabled);
    assert!(!routing_gate.tct_compiler_route.uses_syntax_renderer_api);
    assert!(routing_gate.compiler_boundary.sidecar_only);
    assert!(!routing_gate.compiler_boundary.tct_compiler_route_allowed);
    assert!(
        routing_gate
            .compiler_boundary
            .preserves_json_schema_backend_contract
    );
    assert!(
        routing_gate
            .json_backend_parity
            .stable_json_schema_backend_unchanged
    );
    for blocker in [
        "JSON-backend parity gates",
        "target-agnostic syntax boundary selection",
        "strict/recovery decode behavior",
        "consumed-token accounting",
        "token/vocabulary/BPE invariants",
        "reproducibility",
        "audit coverage",
    ] {
        assert!(
            routing_gate
                .blockers
                .iter()
                .any(|candidate| candidate == blocker),
            "missing routing blocker {blocker}"
        );
    }
    assert_eq!(
        routing_gate.completed_promotion_class,
        "syntax backend production TctCompiler routing gate"
    );
    assert_eq!(
        routing_gate.next_missing_stable_promotion_class,
        TCT_COMPILER_ROUTING_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
}

