#[test]
fn syntax_backend_strict_recovery_decode_routing_gate_matches_target_boundary() {
    let target_gate = load_target_agnostic_routing_boundary_gate();
    let envelope = load_envelope();
    let decode_gate = load_strict_recovery_decode_routing_gate();

    decode_gate
        .validate_against_target_boundary_and_envelope(&target_gate, &envelope)
        .expect("strict/recovery decode routing fixture should match target boundary");

    assert_eq!(
        STRICT_RECOVERY_ROUTING_FIXTURE_PATH,
        "tests/fixtures/syntax_backend/strict-recovery-decode-routing-gate-v1.json"
    );
    assert_eq!(
        decode_gate.artifact_kind,
        STRICT_RECOVERY_ROUTING_ARTIFACT_KIND
    );
    assert_eq!(
        decode_gate
            .source_target_agnostic_routing_boundary_gate
            .fixture_path,
        TARGET_AGNOSTIC_ROUTING_FIXTURE_PATH
    );
    assert_eq!(
        decode_gate.source_generated_artifact_envelope.fixture_path,
        ENVELOPE_FIXTURE_PATH
    );
    assert!(decode_gate.compiler_boundary.sidecar_only);
    assert!(!decode_gate.compiler_boundary.tct_compiler_route_allowed);
    assert!(!decode_gate.route_state.route_registered);
    assert!(!decode_gate.route_state.route_enabled);
    assert!(!decode_gate.route_state.uses_syntax_renderer_api);
    assert!(
        decode_gate
            .strict_decode_contract
            .strict_decode_authoritative
    );
    assert!(decode_gate.strict_decode_contract.rejects_trailing_tokens);
    assert!(
        decode_gate
            .strict_decode_contract
            .transition_acceptance_equals_admissible_mask
    );
    assert!(
        decode_gate
            .strict_decode_contract
            .records_consumed_prefix_requirement
    );
    assert!(
        decode_gate
            .strict_decode_contract
            .does_not_default_partial_prefixes
    );
    for failure_kind in [
        "eof",
        "trailing_tokens",
        "malformed_structural_tokens",
        "malformed_payload_tokens",
        "invalid_parser_backed_payloads",
        "partial_prefix_failures",
        "non_admissible_marker_tokens",
    ] {
        assert!(
            decode_gate
                .strict_decode_contract
                .failure_kinds
                .iter()
                .any(|candidate| candidate == failure_kind),
            "missing strict failure kind {failure_kind}"
        );
    }
    assert!(
        decode_gate
            .recovery_decode_contract
            .normalizes_trailing_pad_only
    );
    assert!(
        decode_gate
            .recovery_decode_contract
            .normalization_requires_complete_syntax_prefix
    );
    assert!(decode_gate.recovery_decode_contract.rejects_non_pad_surplus);
    assert!(
        decode_gate
            .recovery_decode_contract
            .does_not_promote_prefix_completion
    );
    for hard_error_kind in [
        "eof",
        "non_pad_surplus",
        "malformed_structural_tokens",
        "malformed_payload_tokens",
        "invalid_parser_backed_payloads",
        "partial_prefix_failures",
    ] {
        assert!(
            decode_gate
                .recovery_decode_contract
                .hard_error_kinds
                .iter()
                .any(|candidate| candidate == hard_error_kind),
            "missing recovery hard error kind {hard_error_kind}"
        );
    }
    for marker in [
        "strict_decode_rejects_eof",
        "strict_decode_rejects_malformed_structural_tokens",
        "generated_csharp_recovery_normalizes_trailing_pad_only",
        "generated_go_decode_rejects_invalid_identifier_payloads_with_accounting",
        "recovery_policy_rejects_partial_prefix_errors_without_result",
    ] {
        assert!(
            decode_gate
                .generated_codec_evidence
                .required_test_markers
                .iter()
                .any(|candidate| candidate == marker),
            "missing generated codec marker {marker}"
        );
    }
    assert_eq!(
        decode_gate
            .generated_codec_evidence
            .target_agnostic_compiler_route_metadata_field,
        "target_agnostic_compiler_route"
    );
    for evidence in [
        "csharp_minimal_class_syntax_v0",
        "csharp_local_string_return_literal_syntax_v0",
        "go_minimal_function_syntax_v0",
        "go_local_declaration_syntax_v0",
        "generated_go_minimal_function_real_source_strings_compare_demo",
    ] {
        assert!(
            decode_gate
                .generated_codec_evidence
                .target_agnostic_compiler_route_evidence
                .iter()
                .any(|candidate| candidate == evidence),
            "missing strict/recovery compiler-route evidence {evidence}"
        );
    }
    assert_eq!(
        decode_gate.completed_promotion_class,
        "syntax backend strict/recovery decode routing gate"
    );
    assert_eq!(
        decode_gate.next_missing_stable_promotion_class,
        STRICT_RECOVERY_ROUTING_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
}

