#[test]
fn syntax_backend_stable_promotion_review_gate_matches_audit_coverage_gate() {
    let reproducibility_gate = load_reproducibility_routing_gate();
    let audit_gate = load_audit_coverage_routing_gate();
    audit_gate
        .validate_against_reproducibility_gate(&reproducibility_gate)
        .expect("audit coverage routing fixture should match reproducibility gate");
    let review_gate = load_stable_promotion_review_gate();

    review_gate
        .validate_against_audit_coverage_gate(&audit_gate)
        .expect("stable promotion review fixture should match audit coverage gate");

    assert_eq!(
        STABLE_PROMOTION_REVIEW_FIXTURE_PATH,
        "tests/fixtures/syntax_backend/stable-promotion-review-gate-v1.json"
    );
    assert_eq!(
        review_gate.artifact_kind,
        STABLE_PROMOTION_REVIEW_ARTIFACT_KIND
    );
    assert_eq!(
        review_gate.source_audit_coverage_routing_gate.fixture_path,
        AUDIT_COVERAGE_ROUTING_FIXTURE_PATH
    );
    assert!(review_gate.compiler_boundary.sidecar_only);
    assert!(!review_gate.compiler_boundary.tct_compiler_route_allowed);
    assert!(!review_gate.route_state.route_registered);
    assert!(!review_gate.route_state.route_enabled);
    assert!(!review_gate.route_state.stable_backend_promoted);
    assert!(
        review_gate
            .route_state
            .first_production_route_slice_allowed_next
    );
    for completed in [
        "syntax backend production TctCompiler routing gate",
        "syntax backend JSON-backend parity routing gate",
        "syntax backend target-agnostic routing boundary gate",
        "syntax backend strict/recovery decode routing gate",
        "syntax backend consumed-token accounting routing gate",
        "syntax backend token/vocabulary/BPE routing gate",
        "syntax backend reproducibility routing gate",
        "syntax backend audit coverage routing gate",
    ] {
        assert!(
            review_gate
                .review_contract
                .completed_route_boundary_classes
                .iter()
                .any(|candidate| candidate == completed),
            "missing completed route-boundary class {completed}"
        );
    }
    for category in [
        "input_validation",
        "generated_code_compilation",
        "semantic_round_trips",
        "strict_recovery_decode",
        "consumed_token_accounting",
        "token_vocabulary_bpe",
        "generated_artifact_reproducibility",
        "maintained_documentation",
        "audit_coverage",
        "json_backend_parity",
    ] {
        assert!(
            review_gate
                .review_contract
                .json_backend_grade_categories
                .iter()
                .any(|candidate| candidate == category),
            "missing JSON-backend-grade category {category}"
        );
    }
    assert_eq!(
        review_gate.promotion_decision.decision,
        "ready_for_first_production_route_implementation_slice"
    );
    assert_eq!(
        review_gate.completed_promotion_class,
        "syntax backend stable promotion review gate"
    );
    assert_eq!(
        review_gate.next_missing_stable_promotion_class,
        STABLE_PROMOTION_REVIEW_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
}

