#[test]
fn syntax_backend_production_route_gate_matches_stable_review_gate() {
    let audit_gate = load_audit_coverage_routing_gate();
    let review_gate = load_stable_promotion_review_gate();
    review_gate
        .validate_against_audit_coverage_gate(&audit_gate)
        .expect("stable promotion review fixture should match audit coverage gate");
    let route_gate = load_production_route_implementation_gate();

    route_gate
        .validate_against_stable_review_gate(&review_gate)
        .expect("production route fixture should match stable promotion review gate");

    assert_eq!(route_gate.artifact_kind, PRODUCTION_ROUTE_ARTIFACT_KIND);
    assert_eq!(
        PRODUCTION_ROUTE_FIXTURE_PATH,
        "tests/fixtures/syntax_backend/production-route-implementation-gate-v1.json"
    );
    assert_eq!(
        route_gate.source_stable_promotion_review_gate.fixture_path,
        STABLE_PROMOTION_REVIEW_FIXTURE_PATH
    );
    assert!(route_gate.route_state.route_registered);
    assert!(route_gate.route_state.route_enabled);
    assert!(!route_gate.route_state.public_api_changed);
    assert!(!route_gate.route_state.uses_json_schema_compiler);
    assert!(route_gate.route_state.uses_syntax_renderer_api);
    assert!(route_gate.route_state.stable_backend_promoted);
    assert_eq!(
        route_gate.stable_metadata.stable_backend_scope,
        STABLE_BACKEND_SCOPE
    );
    assert_eq!(
        route_gate.stable_metadata.completed_promotion_class,
        STABLE_METADATA_PROMOTION_COMPLETED_CLASS
    );
    assert_eq!(
        route_gate.route_state.route_entrypoint,
        PRODUCTION_ROUTE_ENTRYPOINT
    );
    assert!(!route_gate.compiler_boundary.sidecar_only);
    assert!(route_gate.compiler_boundary.tct_compiler_route_allowed);
    assert!(
        !route_gate
            .compiler_boundary
            .generated_json_schema_output_changed
    );
    assert!(!route_gate.compiler_boundary.core_compiler_path_changed);
    assert!(
        route_gate
            .compiler_boundary
            .preserves_json_schema_backend_contract
    );
    for target in ["toy", "csharp", "go"] {
        assert!(
            route_gate
                .route_contract
                .target_ids
                .iter()
                .any(|candidate| candidate == target),
            "missing route target {target}"
        );
    }
    assert_eq!(
        route_gate.completed_promotion_class,
        PRODUCTION_ROUTE_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        route_gate.next_missing_stable_promotion_class,
        PRODUCTION_ROUTE_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
}

#[test]
fn syntax_backend_compiler_route_entrypoint_infers_go_and_csharp_targets() {
    let route_gate = load_production_route_implementation_gate();
    assert_eq!(
        route_gate
            .route_contract
            .target_agnostic_compiler_entrypoint,
        SYNTAX_COMPILER_ROUTE_ENTRYPOINT
    );
    assert_eq!(
        route_gate.route_contract.target_inference_source,
        ROUTE_SETUP_SOURCE_OF_TRUTH
    );
    for evidence in [
        "csharp_minimal_class_syntax_v0",
        "csharp_local_string_return_literal_syntax_v0",
        "go_minimal_function_syntax_v0",
        "go_local_declaration_syntax_v0",
        "generated_go_minimal_function_real_source_strings_compare_demo",
    ] {
        assert!(
            route_gate
                .route_contract
                .paired_route_evidence
                .iter()
                .any(|candidate| candidate == evidence),
            "missing paired route evidence {evidence}"
        );
    }
    for evidence in [
        "csharp_minimal_class_syntax_v0",
        "csharp_local_string_return_literal_syntax_v0",
        "go_minimal_function_syntax_v0",
        "go_local_declaration_syntax_v0",
    ] {
        assert!(
            route_gate
                .route_contract
                .parser_backed_reproducibility_evidence
                .iter()
                .any(|candidate| candidate == evidence),
            "missing parser-backed reproducibility route evidence {evidence}"
        );
    }
    for evidence in [
        "csharp_minimal_class_syntax_v0",
        "csharp_local_string_return_literal_syntax_v0",
        "go_minimal_function_syntax_v0",
        "go_local_declaration_syntax_v0",
        "generated_go_minimal_function_real_source_strings_compare_demo",
    ] {
        assert!(
            route_gate
                .route_contract
                .strict_recovery_decode_route_evidence
                .iter()
                .any(|candidate| candidate == evidence),
            "missing strict/recovery route evidence {evidence}"
        );
        assert!(
            route_gate
                .route_contract
                .consumed_token_accounting_route_evidence
                .iter()
                .any(|candidate| candidate == evidence),
            "missing consumed-token route evidence {evidence}"
        );
        assert!(
            route_gate
                .route_contract
                .token_vocabulary_bpe_route_evidence
                .iter()
                .any(|candidate| candidate == evidence),
            "missing token/vocabulary/BPE route evidence {evidence}"
        );
    }

    let (csharp_grammar, csharp_sidecar) = csharp_route_input();
    let csharp = compile_checked_syntax_compiler_route(SyntaxCompilerRouteRequest {
        grammar: &csharp_grammar,
        sidecar: &csharp_sidecar,
    })
    .expect("target-agnostic compiler route should infer C# from checked metadata");
    assert_eq!(csharp.target, "csharp");
    assert_eq!(
        csharp.source,
        render_csharp_syntax_codec_fixture(&csharp_sidecar)
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["entrypoint"],
        SYNTAX_COMPILER_ROUTE_ENTRYPOINT
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["delegates_to"],
        PRODUCTION_ROUTE_ENTRYPOINT
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["completed_promotion_class"],
        SYNTAX_COMPILER_ROUTE_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["generated_code_gate_completed_promotion_class"],
        SYNTAX_COMPILER_GENERATED_CODE_GATE_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["strict_recovery_decode_completed_promotion_class"],
        SYNTAX_COMPILER_STRICT_RECOVERY_DECODE_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["consumed_token_accounting_completed_promotion_class"],
        SYNTAX_COMPILER_CONSUMED_TOKEN_ACCOUNTING_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["token_vocabulary_bpe_completed_promotion_class"],
        SYNTAX_COMPILER_TOKEN_VOCABULARY_BPE_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["paired_route_evidence"]["csharp_fixture"],
        CSHARP_METADATA_PATH
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["paired_route_evidence"]["csharp_non_minimal_fixture"],
        CSHARP_LOCAL_STRING_RETURN_LITERAL_METADATA_PATH
    );
    assert_eq!(
        csharp.metadata["target_agnostic_compiler_route"]["next_missing_stable_promotion_class"],
        PRODUCTION_ROUTE_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );

    let (go_grammar, go_sidecar) = go_route_input();
    let go = compile_checked_syntax_compiler_route(SyntaxCompilerRouteRequest {
        grammar: &go_grammar,
        sidecar: &go_sidecar,
    })
    .expect("target-agnostic compiler route should infer Go from checked metadata");
    assert_eq!(go.target, "go");
    assert_eq!(go.source, render_go_syntax_codec_fixture(&go_sidecar));
    assert!(
        go.source
            .contains("generated_go_minimal_function_real_source_strings_compare_demo")
    );
    assert_eq!(
        go.metadata["target_agnostic_compiler_route"]["target"],
        "go"
    );
    assert_eq!(
        go.metadata["target_agnostic_compiler_route"]["paired_route_evidence"]["go_real_source_path"],
        "tests/fixtures/go_syntax_corpus/src/strings/compare.go"
    );
    assert_eq!(
        go.metadata["target_agnostic_compiler_route"]["paired_route_evidence"]["go_non_minimal_fixture"],
        GO_LOCAL_DECLARATION_METADATA_PATH
    );
    assert_eq!(
        go.metadata["target_agnostic_compiler_route"]["paired_route_evidence"]["go_real_source_marker"],
        "generated_go_minimal_function_real_source_strings_compare_demo"
    );
    for evidence in [
        "csharp_minimal_class_syntax_v0",
        "csharp_local_string_return_literal_syntax_v0",
        "go_minimal_function_syntax_v0",
        "go_local_declaration_syntax_v0",
        "generated_go_minimal_function_real_source_strings_compare_demo",
    ] {
        assert!(
            go.metadata["target_agnostic_compiler_route"]["generated_code_gate_representatives"]
                .as_array()
                .unwrap()
                .iter()
                .any(|candidate| candidate == evidence),
            "missing generated-code gate representative {evidence}"
        );
    }
    for evidence in [
        "csharp_minimal_class_syntax_v0",
        "csharp_local_string_return_literal_syntax_v0",
        "go_minimal_function_syntax_v0",
        "go_local_declaration_syntax_v0",
        "generated_go_minimal_function_real_source_strings_compare_demo",
    ] {
        assert!(
            go.metadata["target_agnostic_compiler_route"]["strict_recovery_decode_route_evidence"]
                .as_array()
                .unwrap()
                .iter()
                .any(|candidate| candidate == evidence),
            "missing strict/recovery route metadata evidence {evidence}"
        );
        assert!(
            go.metadata["target_agnostic_compiler_route"]["consumed_token_accounting_route_evidence"]
                .as_array()
                .unwrap()
                .iter()
                .any(|candidate| candidate == evidence),
            "missing consumed-token route metadata evidence {evidence}"
        );
        assert!(
            go.metadata["target_agnostic_compiler_route"]["token_vocabulary_bpe_route_evidence"]
                .as_array()
                .unwrap()
                .iter()
                .any(|candidate| candidate == evidence),
            "missing token/vocabulary/BPE route metadata evidence {evidence}"
        );
    }
    for invariant_case in [
        "pad_token_below_vocab_size",
        "pad_token_outside_raw_base_ranges",
        "structural_ranges_do_not_overlap_payload_ranges",
        "bpe_range_starts_at_raw_base_vocab_size",
        "bpe_range_below_vocab_size_or_relocates_pad",
        "bpe_ids_do_not_collide_with_pad_token",
        "emitted_tokens_below_vocab_size",
        "emitted_tokens_exclude_pad_token",
    ] {
        assert!(
            go.metadata["target_agnostic_compiler_route"]["token_vocabulary_bpe_invariant_cases"]
                .as_array()
                .unwrap()
                .iter()
                .any(|candidate| candidate == invariant_case),
            "missing token/vocabulary/BPE route invariant case {invariant_case}"
        );
    }
    assert_eq!(
        go.metadata["target_agnostic_compiler_route"]["rejects_arena_ir_boundaries"],
        true
    );
    assert!(!go.metadata_sha256.is_empty());
}

