#[test]
fn syntax_backend_production_route_rejects_target_mismatch() {
    let (grammar, sidecar) = toy_route_input();

    let error = compile_checked_syntax_production_route(SyntaxProductionRouteRequest {
        target: SyntaxProductionRouteTarget::Go,
        grammar: &grammar,
        sidecar: &sidecar,
    })
    .expect_err("production route must reject mismatched checked input targets");

    assert_eq!(error.field(), "grammar.provenance.source_kind");
}

#[test]
fn syntax_backend_production_route_rejects_missing_stable_metadata_claim() {
    let review_gate = load_stable_promotion_review_gate();
    let mut route_gate = load_production_route_implementation_gate();
    route_gate.route_state.stable_backend_promoted = false;

    let error = route_gate
        .validate_against_stable_review_gate(&review_gate)
        .expect_err("production route gate must require stable metadata promotion");

    assert_eq!(error.field(), "route_state.stable_backend_promoted");
}

#[test]
fn syntax_backend_validation_matrix_gate_matches_production_route() {
    let route_gate = load_production_route_implementation_gate();
    let matrix_gate = load_validation_matrix_gate();
    let artifacts = validation_matrix_route_artifacts();

    matrix_gate
        .validate_against_production_route_gate(&route_gate, &artifacts)
        .expect("validation matrix fixture should bind JSON-backend-grade categories to compiler-route evidence");

    assert_eq!(matrix_gate.artifact_kind, VALIDATION_MATRIX_ARTIFACT_KIND);
    assert_eq!(
        matrix_gate.next_missing_stable_promotion_class,
        VALIDATION_MATRIX_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
    assert_eq!(
        matrix_gate.execution_report_policy.report_artifact_kind,
        VALIDATION_MATRIX_EXECUTION_REPORT_ARTIFACT_KIND
    );
    assert_eq!(
        matrix_gate.execution_report_policy.generated_report_path,
        VALIDATION_MATRIX_EXECUTION_REPORT_PATH
    );
    assert_eq!(
        matrix_gate
            .execution_report_policy
            .source_report_producer_command,
        VALIDATION_MATRIX_EXECUTION_REPORT_PRODUCER_COMMAND
    );
    assert_eq!(
        matrix_gate
            .execution_report_policy
            .source_report_validator_command,
        VALIDATION_MATRIX_EXECUTION_REPORT_VALIDATOR_COMMAND
    );
    assert_eq!(
        matrix_gate
            .execution_report_policy
            .completed_promotion_class,
        VALIDATION_MATRIX_EXECUTION_REPORT_COMPLETED_PROMOTION_CLASS
    );
    assert!(
        matrix_gate
            .execution_report_policy
            .executes_required_commands
    );
    assert!(
        matrix_gate
            .execution_report_policy
            .records_per_category_results
    );
    assert!(!matrix_gate.execution_report_policy.arena_ir_proof_used);
    assert!(
        !matrix_gate
            .stable_promotion_blocker
            .requires_matrix_execution
    );
    assert!(matrix_gate.stable_promotion_blocker.stable_backend_promoted);
    assert_eq!(
        matrix_gate.stable_promotion_blocker.stable_backend_scope,
        STABLE_BACKEND_SCOPE
    );
    assert!(
        matrix_gate
            .stable_promotion_blocker
            .requires_matrix_preservation
    );
    let categories: BTreeSet<_> = matrix_gate
        .matrix_contract
        .categories
        .iter()
        .map(|category| category.category_id.as_str())
        .collect();
    for category in VALIDATION_MATRIX_REQUIRED_CATEGORIES {
        assert!(categories.contains(category), "missing category {category}");
    }
    for artifact in &artifacts {
        let route = &artifact.metadata["target_agnostic_compiler_route"];
        assert_eq!(
            route["validation_matrix_completed_promotion_class"],
            "syntax backend JSON-backend-grade validation matrix route ownership gate"
        );
        for evidence in VALIDATION_MATRIX_ROUTE_EVIDENCE {
            assert!(
                route["validation_matrix_route_evidence"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|candidate| candidate == *evidence),
                "missing validation matrix route evidence {evidence}"
            );
        }
    }
}

#[test]
fn syntax_backend_validation_matrix_rejects_missing_category() {
    let route_gate = load_production_route_implementation_gate();
    let mut matrix_gate = load_validation_matrix_gate();
    matrix_gate
        .matrix_contract
        .categories
        .retain(|category| category.category_id != "audit_coverage");

    let error = matrix_gate
        .validate_against_production_route_gate(&route_gate, &validation_matrix_route_artifacts())
        .expect_err("validation matrix gate must reject missing JSON-backend-grade categories");

    assert_eq!(error.field(), "matrix_contract.categories");
}

#[test]
fn syntax_backend_validation_matrix_rejects_arena_ir_control_as_proof() {
    let route_gate = load_production_route_implementation_gate();
    let mut matrix_gate = load_validation_matrix_gate();
    matrix_gate.matrix_contract.categories[0]
        .sidecar_control_gate
        .module_path = "src/goir.rs".to_string();

    let error = matrix_gate
        .validate_against_production_route_gate(&route_gate, &validation_matrix_route_artifacts())
        .expect_err("validation matrix gate must reject arena IR as syntax-level proof");

    assert_eq!(
        error.field(),
        "matrix_contract.category.sidecar_control_gate"
    );
}

#[test]
fn syntax_backend_validation_matrix_execution_preservation_matches_matrix() {
    let matrix_gate = load_validation_matrix_gate();
    let preservation_gate = load_validation_matrix_preservation_gate();

    preservation_gate
        .validate_against_validation_matrix_gate(&matrix_gate)
        .expect("execution preservation fixture should pin the matrix refresh policy");

    assert_eq!(
        preservation_gate.artifact_kind,
        VALIDATION_MATRIX_PRESERVATION_ARTIFACT_KIND
    );
    assert_eq!(
        preservation_gate.next_missing_stable_promotion_class,
        VALIDATION_MATRIX_PRESERVATION_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
    assert_eq!(
        preservation_gate.source_validation_matrix_gate.fixture_path,
        VALIDATION_MATRIX_FIXTURE_PATH
    );
    assert_eq!(
        preservation_gate
            .execution_evidence_policy
            .generated_report_path,
        VALIDATION_MATRIX_EXECUTION_REPORT_PATH
    );
    assert!(
        preservation_gate
            .execution_evidence_policy
            .report_refresh_required_before_stable_promotion
    );
    assert!(
        !preservation_gate
            .execution_evidence_policy
            .report_checked_in
    );
    assert!(!preservation_gate.execution_evidence_policy.logs_checked_in);
    assert!(
        !preservation_gate
            .execution_evidence_policy
            .stable_report_hash_pinned
    );
    assert!(
        !preservation_gate
            .execution_evidence_policy
            .arena_ir_proof_used
    );
    assert!(
        preservation_gate
            .execution_evidence_policy
            .json_schema_backend_unchanged
    );
    for category in VALIDATION_MATRIX_REQUIRED_CATEGORIES {
        assert!(
            preservation_gate
                .preserved_report_contract
                .required_categories
                .iter()
                .any(|candidate| candidate == category),
            "missing preserved category {category}"
        );
    }
}

