#[test]
fn syntax_backend_final_promotion_decision_matches_preserved_matrix() {
    let preservation_gate = load_validation_matrix_preservation_gate();
    let matrix_gate = load_validation_matrix_gate();
    let route_gate = load_production_route_implementation_gate();
    let json_parity_gate = load_json_backend_parity_gate();
    let decision_gate = load_final_promotion_decision_gate();

    decision_gate
        .validate_against_preserved_matrix(
            &preservation_gate,
            &matrix_gate,
            &route_gate,
            &json_parity_gate,
        )
        .expect("final decision fixture should consume preserved matrix evidence");

    assert_eq!(
        decision_gate.artifact_kind,
        FINAL_PROMOTION_DECISION_ARTIFACT_KIND
    );
    assert_eq!(
        FINAL_PROMOTION_DECISION_FIXTURE_PATH,
        "tests/fixtures/syntax_backend/final-stable-promotion-decision-v1.json"
    );
    assert_eq!(
        decision_gate
            .source_validation_matrix_preservation_gate
            .fixture_path,
        VALIDATION_MATRIX_PRESERVATION_FIXTURE_PATH
    );
    assert_eq!(
        decision_gate.evidence_snapshot.execution_report_path,
        VALIDATION_MATRIX_EXECUTION_REPORT_PATH
    );
    assert!(decision_gate.promotion_decision.stable_ready);
    assert!(
        !decision_gate
            .promotion_decision
            .stable_backend_promoted_in_this_gate
    );
    assert!(
        decision_gate
            .promotion_decision
            .remaining_blockers
            .is_empty()
    );
    assert!(!decision_gate.promotion_decision.arena_ir_proof_used);
    assert_eq!(
        decision_gate.next_missing_stable_promotion_class,
        FINAL_PROMOTION_DECISION_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
}

