#[test]
fn syntax_backend_route_manifest_matches_route_table_and_source_corpus() {
    let route_gate = load_production_route_implementation_gate();
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let route_manifest = load_production_route_manifest();

    route_manifest
        .validate_against_route_gate_and_source_corpus(&route_gate, &source_corpus_gate)
        .expect("route manifest fixture should match route table and source-corpus gate");

    assert_eq!(route_manifest.artifact_kind, ROUTE_MANIFEST_ARTIFACT_KIND);
    assert_eq!(
        ROUTE_MANIFEST_FIXTURE_PATH,
        "tests/fixtures/syntax_backend/production-route-manifest-v1.json"
    );
    assert_eq!(
        route_manifest.production_route_fixture_path,
        PRODUCTION_ROUTE_FIXTURE_PATH
    );
    assert_eq!(
        route_manifest.source_corpus_evidence_fixture_path,
        SOURCE_CORPUS_EVIDENCE_FIXTURE_PATH
    );
    assert_eq!(
        route_manifest.route_setup_source_of_truth,
        ROUTE_SETUP_SOURCE_OF_TRUTH
    );
    assert_eq!(route_manifest.route_entrypoint, PRODUCTION_ROUTE_ENTRYPOINT);
    assert_eq!(route_manifest.route_manifest_loader, ROUTE_MANIFEST_LOADER);
    assert_eq!(
        route_manifest.projector_metadata_setup_source,
        tct::syntax_production_route::PROJECTOR_METADATA_SETUP_SOURCE_OF_TRUTH
    );
    assert_eq!(
        route_manifest.projector_metadata_setup_fields,
        tct::syntax_production_route::projector_metadata_setup_fields()
    );
    assert_eq!(
        route_manifest.constructs,
        build_syntax_production_route_manifest().constructs
    );
    assert_eq!(
        route_manifest.constructs.len(),
        SYNTAX_PRODUCTION_ROUTE_CONSTRUCTS.len()
    );
    assert_eq!(
        route_manifest.completed_promotion_class,
        ROUTE_MANIFEST_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        route_manifest.loader_completed_promotion_class,
        ROUTE_MANIFEST_LOADER_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        route_manifest.projector_metadata_setup_completed_promotion_class,
        PROJECTOR_METADATA_SETUP_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        route_manifest.next_missing_stable_promotion_class,
        ROUTE_MANIFEST_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
    assert_eq!(
        route_manifest.next_missing_stable_promotion_class,
        PRODUCTION_ROUTE_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
    assert!(
        route_manifest
            .no_stable_claims
            .iter()
            .any(|claim| claim == "no_build_script_route_generation")
    );
    let manifest_grammar_ids = route_manifest
        .constructs
        .iter()
        .map(|construct| construct.grammar_id.as_str())
        .collect::<BTreeSet<_>>();
    assert!(
        manifest_grammar_ids.contains("go_strings_compare_source_file_syntax_v0"),
        "checked manifest should include the registry-owned strings/compare source-file route"
    );
    let route_grammar_ids = SYNTAX_PRODUCTION_ROUTE_CONSTRUCTS
        .iter()
        .map(|construct| construct.grammar_id)
        .collect::<BTreeSet<_>>();
    assert_eq!(manifest_grammar_ids, route_grammar_ids);
    for construct in &route_manifest.constructs {
        let route_construct = syntax_production_route_construct(&construct.grammar_id)
            .expect("manifest construct should map back to route table");
        assert_eq!(
            construct.projector_metadata_setup,
            syntax_production_route_projector_metadata_setup(route_construct)
        );
        assert_eq!(
            construct.projector_metadata_setup.checked_metadata_path,
            construct.metadata_path
        );
        assert!(
            construct
                .projector_metadata_setup
                .generated_output_path
                .starts_with("target/")
        );
        assert!(
            construct
                .projector_metadata_setup
                .route_manifest_projector_backed
        );
    }
}

