#[test]
fn syntax_backend_source_corpus_evidence_fixture_builds_parser_backed_records() {
    assert_eq!(
        SOURCE_CORPUS_EVIDENCE_FIXTURE_PATH,
        SOURCE_CORPUS_EVIDENCE_AUDIT_FIXTURE_PATH
    );

    let route_gate = load_production_route_implementation_gate();
    let route_manifest = load_production_route_manifest();
    let evidence_gate = load_source_corpus_evidence_gate();

    evidence_gate
        .validate_against_production_route_gate(&route_gate, &route_manifest)
        .expect("source corpus evidence fixture should match production route gate");
    let report = evidence_gate
        .build_report(&route_gate, &route_manifest)
        .expect(
            "source corpus evidence should derive records from checked route manifest metadata",
        );

    assert_eq!(
        evidence_gate.artifact_kind,
        SOURCE_CORPUS_EVIDENCE_ARTIFACT_KIND
    );
    assert_eq!(
        SOURCE_CORPUS_EVIDENCE_FIXTURE_PATH,
        evidence_gate.report_policy.checked_fixture_path
    );
    assert_eq!(
        evidence_gate.report_policy.generated_report_path,
        SOURCE_CORPUS_EVIDENCE_REPORT_PATH
    );
    assert!(!evidence_gate.report_policy.generated_reports_checked_in);
    assert_eq!(
        evidence_gate.completed_promotion_class,
        SOURCE_CORPUS_EVIDENCE_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        evidence_gate.next_missing_stable_promotion_class,
        SOURCE_CORPUS_EVIDENCE_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
    assert_eq!(
        report.records.len(),
        SYNTAX_PRODUCTION_ROUTE_CONSTRUCTS.len()
    );
    assert_eq!(
        report.record_count,
        SYNTAX_PRODUCTION_ROUTE_CONSTRUCTS.len()
    );
    assert_eq!(report.records_sha256.len(), 64);
    assert!(
        !report
            .missing_evidence
            .iter()
            .any(|missing| missing == "go_minimal_function_production_route")
    );
    assert!(
        !report
            .missing_evidence
            .iter()
            .any(|missing| missing == "json_backend_grade_stable_promotion_gate")
    );
    assert!(
        report
            .missing_evidence
            .iter()
            .any(|missing| missing == "source_program_claim_handoff")
    );
    assert!(
        !report
            .missing_evidence
            .iter()
            .any(|missing| missing
                == "csharp_real_source_generated_codec_corpus_completion_evidence")
    );
    assert_eq!(
        evidence_gate.csharp_no_gap_metadata_report.artifact_kind,
        CSHARP_NO_GAP_METADATA_REPORT_ARTIFACT_KIND
    );
    assert_eq!(
        evidence_gate.csharp_no_gap_metadata_report.tool,
        CSHARP_NO_GAP_METADATA_REPORT_TOOL
    );
    assert_eq!(
        evidence_gate.csharp_no_gap_metadata_report.report_path,
        CSHARP_NO_GAP_METADATA_REPORT_PATH
    );
    assert_eq!(
        evidence_gate.csharp_no_gap_metadata_report.report_command,
        CSHARP_NO_GAP_METADATA_REPORT_COMMAND
    );
    assert_eq!(
        evidence_gate.csharp_no_gap_metadata_report.corpus_id,
        CSHARP_NO_GAP_CORPUS_ID
    );
    assert_eq!(
        evidence_gate
            .csharp_no_gap_metadata_report
            .expected_file_count,
        CSHARP_NO_GAP_EXPECTED_FILE_COUNT
    );
    assert_eq!(
        evidence_gate
            .csharp_no_gap_metadata_report
            .expected_unsupported_node_kind_count,
        0
    );
    assert_eq!(
        evidence_gate
            .csharp_no_gap_metadata_report
            .expected_unsupported_gap_count,
        0
    );
    assert!(
        evidence_gate
            .csharp_no_gap_metadata_report
            .expected_next_smallest_tranche
            .is_none()
    );
    assert!(
        evidence_gate
            .csharp_no_gap_metadata_report
            .no_stable_claims
            .iter()
            .any(|claim| claim == "no_generated_codec_real_source_claim")
    );
    assert_eq!(
        report.csharp_no_gap_metadata_report,
        evidence_gate.csharp_no_gap_metadata_report
    );
    assert_eq!(
        evidence_gate.report_policy.source_report_validator_command,
        REPORT_VALIDATOR_COMMAND
    );
    assert!(
        evidence_gate
            .report_policy
            .source_report_validator_available
    );
    assert_eq!(
        REPORT_VALIDATOR_COMPLETED_PROMOTION_CLASS,
        "syntax backend parser-backed source corpus report validator tranche"
    );
    evidence_gate
        .validate_report(&route_gate, &route_manifest, &report)
        .expect("source corpus evidence report should validate against current route gate");

    let route_grammar_ids = SYNTAX_PRODUCTION_ROUTE_CONSTRUCTS
        .iter()
        .map(|construct| construct.grammar_id)
        .collect::<BTreeSet<_>>();
    let report_grammar_ids = report
        .records
        .iter()
        .map(|record| record.grammar_id.as_str())
        .collect::<BTreeSet<_>>();
    assert_eq!(route_grammar_ids, report_grammar_ids);

    let mut targets = BTreeSet::new();
    for record in &report.records {
        targets.insert(record.target_id.as_str());
        let construct = syntax_production_route_construct(&record.grammar_id)
            .expect("source corpus record should map back to production route construct");
        assert_eq!(record.target_id, construct.target_id);
        assert_eq!(
            record.completed_promotion_class,
            construct.completed_promotion_class
        );
        assert_eq!(record.metadata_path, construct.metadata_path);
        assert_eq!(
            record.projector_metadata_setup,
            syntax_production_route_projector_metadata_setup(construct)
        );
        assert_eq!(
            record.projector_metadata_setup.checked_metadata_path,
            record.metadata_path
        );
        assert!(
            record
                .projector_metadata_setup
                .generated_output_path
                .starts_with("target/")
        );
        assert_eq!(
            record.generated_test_markers,
            construct
                .generated_test_markers
                .iter()
                .map(|marker| (*marker).to_string())
                .collect::<Vec<_>>()
        );
        assert!(record.source_path.ends_with(".go") || record.source_path.ends_with(".cs"));
        assert_eq!(record.source_sha256.len(), 64);
        assert_eq!(record.metadata_sha256.len(), 64);
        assert_eq!(
            record.parser.tool,
            if record.target_id == "csharp" {
                "dotnet"
            } else {
                "go"
            }
        );
        assert!(!record.parser.version.is_empty());
        assert_eq!(record.generated_codec.rendered_source_sha256.len(), 64);
        assert_eq!(
            record.generated_codec.generated_codec_metadata_sha256.len(),
            64
        );
        assert_eq!(
            record.generated_codec.generated_crate_identity_sha256.len(),
            64
        );
        assert_eq!(record.generated_codec.generation_options_sha256.len(), 64);
        assert_eq!(
            record.token_layout["sha256"]
                .as_str()
                .expect("source corpus token layout should carry a hash")
                .len(),
            64
        );
        assert!(record.token_layout["bpe_boundary"].is_object());
        assert!(record.bpe.bpe_boundary.is_object());
        assert!(!record.bpe.merge_artifact_used);
        assert!(record.bpe.merge_fingerprints.is_empty());
        assert_eq!(
            record.route_metadata.accepted_input,
            "checked GrammarIR -> StructuralModel"
        );
        assert_eq!(
            record.route_metadata.route_entrypoint,
            PRODUCTION_ROUTE_ENTRYPOINT
        );
        assert_eq!(
            record.route_metadata.route_gate,
            "syntax-production-route-v0"
        );
        assert!(record.route_metadata.stable_backend_promoted);
        assert!(!record.route_metadata.generated_json_schema_output_changed);
        assert!(!record.route_metadata.core_compiler_path_changed);
    }

    assert_eq!(targets, BTreeSet::from(["csharp", "go"]));
}

