#[test]
fn syntax_backend_csharp_real_source_generated_codec_corpus_consumes_feasibility_gate() {
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let route_manifest = load_production_route_manifest();
    let csharp_corpus_manifest = load_csharp_real_source_corpus_manifest();
    let feasibility_gate = load_csharp_real_source_generated_codec_feasibility_gate();
    let corpus_gate = load_csharp_real_source_generated_codec_corpus_gate();
    let corpus_fixture: serde_json::Value =
        serde_json::from_str(CSHARP_REAL_SOURCE_GENERATED_CODEC_CORPUS_GATE)
            .expect("C# generated-codec corpus fixture should parse as JSON");

    corpus_gate
        .validate_against_sources(
            &source_corpus_gate,
            &route_manifest,
            &csharp_corpus_manifest,
            &feasibility_gate,
        )
        .expect("C# generated-codec corpus gate should preserve supported and blocked records");

    assert_eq!(
        corpus_gate.artifact_kind,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_CORPUS_ARTIFACT_KIND
    );
    assert_eq!(
        corpus_gate.completed_promotion_class,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_CORPUS_COMPLETED_CLASS
    );
    assert_eq!(
        corpus_gate.next_missing_stable_promotion_class,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_CORPUS_NEXT_CLASS
    );
    assert_eq!(
        corpus_gate.generated_codec_report_contract.report_path,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_CORPUS_REPORT_PATH
    );
    assert_eq!(
        corpus_gate.feasibility_gate.feasible_record_count,
        feasibility_gate.feasibility.feasible_record_count
    );
    assert_eq!(
        corpus_gate.feasibility_gate.blocked_record_count,
        feasibility_gate.feasibility.blocked_record_count
    );
    assert_eq!(
        corpus_gate
            .corpus_round_trip
            .generated_codec_round_trip_record_count,
        5
    );
    assert_eq!(corpus_gate.corpus_round_trip.blocked_record_count, 0);
    let shapes_record = corpus_gate
        .corpus_round_trip
        .supported_records
        .iter()
        .find(|record| record.manifest_path == "pattern-matching/Shapes.cs")
        .expect("Shapes.cs should stay a supported C# generated-codec corpus record");
    assert_eq!(shapes_record.tct_token_count, 77);
    assert_eq!(
        shapes_record.payload_sequence_control_token_count,
        Some(282)
    );
    assert_eq!(
        shapes_record.report_path,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_CORPUS_REPORT_PATH
    );
    let logger_record = corpus_gate
        .corpus_round_trip
        .supported_records
        .iter()
        .find(|record| record.manifest_path == "delegates-and-events/Logger.cs")
        .expect("Logger.cs should be promoted to supported C# generated-codec corpus evidence");
    assert_eq!(logger_record.tct_token_count, 29);
    assert_eq!(
        logger_record.payload_sequence_control_token_count,
        Some(340)
    );
    assert_eq!(
        logger_record.report_path,
        "target/tct-syntax-real-source-demo/csharp-logger-generated-codec-demo.json"
    );
    let version_one_record = corpus_gate
        .corpus_round_trip
        .supported_records
        .iter()
        .find(|record| record.manifest_path == "events/VersionOne.cs")
        .expect("VersionOne.cs should be promoted to supported C# generated-codec corpus evidence");
    assert_eq!(version_one_record.tct_token_count, 54);
    assert_eq!(
        version_one_record.payload_sequence_control_token_count,
        Some(337)
    );
    assert_eq!(
        version_one_record.report_path,
        "target/tct-syntax-real-source-demo/csharp-version-one-generated-codec-demo.json"
    );
    let iterator_methods_record = corpus_gate
        .corpus_round_trip
        .supported_records
        .iter()
        .find(|record| record.manifest_path == "iterators/IteratorMethods.cs")
        .expect(
            "IteratorMethods.cs should be promoted to supported C# generated-codec corpus evidence",
        );
    assert_eq!(iterator_methods_record.tct_token_count, 121);
    assert_eq!(
        iterator_methods_record.payload_sequence_control_token_count,
        Some(482)
    );
    assert_eq!(
        iterator_methods_record.report_path,
        "target/tct-syntax-real-source-demo/csharp-iterator-methods-generated-codec-demo.json"
    );
    let loan_record = corpus_gate
        .corpus_round_trip
        .supported_records
        .iter()
        .find(|record| record.manifest_path == "serialization/Loan.cs")
        .expect("Loan.cs should be promoted to supported C# generated-codec corpus evidence");
    assert_eq!(loan_record.tct_token_count, 100);
    assert_eq!(loan_record.payload_sequence_control_token_count, Some(555));
    assert_eq!(
        loan_record.report_path,
        "target/tct-syntax-real-source-demo/csharp-loan-generated-codec-demo.json"
    );
    for record in &corpus_gate.corpus_round_trip.supported_records {
        for required_field in CSHARP_REAL_SOURCE_REPLAY_METADATA_REPORT_FIELDS {
            assert!(
                record
                    .replay_metadata_report_fields
                    .iter()
                    .any(|field| field == required_field),
                "{} should preserve replay metadata field {}",
                record.manifest_path,
                required_field
            );
        }
    }
    assert!(corpus_gate.corpus_round_trip.blocked_records.is_empty());
    assert!(
        corpus_gate
            .corpus_round_trip
            .blocked_records
            .iter()
            .all(|record| record.manifest_path != "delegates-and-events/Logger.cs")
    );
    assert!(
        corpus_gate
            .corpus_round_trip
            .blocked_records
            .iter()
            .all(|record| record.manifest_path != "events/VersionOne.cs")
    );
    assert!(
        corpus_gate
            .corpus_round_trip
            .blocked_records
            .iter()
            .all(|record| record.manifest_path != "iterators/IteratorMethods.cs")
    );
    assert!(
        corpus_gate
            .corpus_round_trip
            .blocked_records
            .iter()
            .all(|record| record.manifest_path != "serialization/Loan.cs")
    );
    assert!(
        corpus_gate
            .no_stable_claims
            .iter()
            .any(|claim| claim == "no_source_program_validity_claim")
    );
    assert_eq!(
        corpus_fixture["generated_codec_report_contract"]["report_env_var"],
        "TCT_CSHARP_COMPILATION_UNIT_SOURCE_FILE_REAL_SOURCE_CODEC_REPORT"
    );
}

