#[test]
fn syntax_backend_csharp_real_source_generated_codec_completion_handoff_consumes_completed_corpus()
{
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let route_manifest = load_production_route_manifest();
    let csharp_corpus_manifest = load_csharp_real_source_corpus_manifest();
    let feasibility_gate = load_csharp_real_source_generated_codec_feasibility_gate();
    let corpus_gate = load_csharp_real_source_generated_codec_corpus_gate();
    let completion_handoff_gate = load_csharp_real_source_generated_codec_completion_handoff_gate();

    corpus_gate
        .validate_against_sources(
            &source_corpus_gate,
            &route_manifest,
            &csharp_corpus_manifest,
            &feasibility_gate,
        )
        .expect("C# generated-codec corpus fixture should be complete before handoff");
    completion_handoff_gate
        .validate_against_corpus(&corpus_gate, &source_corpus_gate)
        .expect("C# completion handoff should consume completed generated-codec corpus");

    assert_eq!(
        completion_handoff_gate.artifact_kind,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_COMPLETION_HANDOFF_ARTIFACT_KIND
    );
    assert_eq!(
        completion_handoff_gate.completed_promotion_class,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_COMPLETION_HANDOFF_COMPLETED_CLASS
    );
    assert_eq!(
        completion_handoff_gate.next_missing_stable_promotion_class,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_COMPLETION_HANDOFF_NEXT_CLASS
    );
    assert_eq!(
        completion_handoff_gate
            .source_generated_codec_corpus
            .supported_record_count,
        5
    );
    assert_eq!(
        completion_handoff_gate
            .source_generated_codec_corpus
            .blocked_record_count,
        0
    );
    assert_eq!(
        completion_handoff_gate
            .source_generated_codec_corpus
            .generated_codec_round_trip_records,
        corpus_gate.corpus_round_trip.supported_records
    );
    assert!(
        completion_handoff_gate
            .source_generated_codec_corpus
            .supported_manifest_paths
            .iter()
            .any(|path| path == "serialization/Loan.cs")
    );
    assert!(
        completion_handoff_gate
            .source_generated_codec_corpus
            .generated_codec_report_paths
            .iter()
            .any(|path| {
                path == "target/tct-syntax-real-source-demo/csharp-loan-generated-codec-demo.json"
            })
    );
    assert!(
        completion_handoff_gate
            .source_generated_codec_corpus
            .generated_codec_report_commands
            .iter()
            .any(|command| command.contains("csharp_compilation_unit_loan_source_file"))
    );
    assert_eq!(
        completion_handoff_gate
            .source_generated_codec_corpus
            .generated_codec_routes,
        vec![CSHARP_REAL_SOURCE_WHOLE_SOURCE_ROUTE_ID.to_string()]
    );
    assert_eq!(
        completion_handoff_gate
            .source_generated_codec_corpus
            .generated_codec_markers,
        vec![CSHARP_REAL_SOURCE_WHOLE_SOURCE_MARKER.to_string()]
    );
    assert!(
        completion_handoff_gate
            .source_corpus_handoff
            .csharp_completion_evidence_consumed
    );
    assert!(
        !completion_handoff_gate
            .source_corpus_handoff
            .remaining_missing_evidence
            .iter()
            .any(|missing| missing
                == "csharp_real_source_generated_codec_corpus_completion_evidence")
    );
    assert!(
        !completion_handoff_gate
            .claim_boundary
            .source_program_validity_claim_allowed
    );
    assert!(
        !completion_handoff_gate
            .claim_boundary
            .type_correctness_claim_allowed
    );
    assert!(!completion_handoff_gate.claim_boundary.arena_ir_proof_used);
    assert!(
        completion_handoff_gate
            .claim_boundary
            .json_schema_backend_preserved
    );
}

