#[test]
#[ignore = "known failure: current-plus report-ingestion manifest pins grammar_artifact_content_sha256 3f091674..., the live unified Go grammar artifact is 9a8f8f6c...; see docs/frontends-development.md"]
fn syntax_backend_shared_generated_codec_state_api_handoff_consumes_go_and_csharp_state_api_evidence()
 {
    let handoff_gate = load_shared_generated_codec_state_api_handoff_gate();
    handoff_gate
        .validate()
        .expect("shared generated-codec state API handoff fixture should validate");

    assert_eq!(
        handoff_gate.artifact_kind,
        SHARED_STATE_API_HANDOFF_ARTIFACT_KIND
    );
    assert_eq!(
        handoff_gate.completed_promotion_class,
        SHARED_STATE_API_HANDOFF_COMPLETED_CLASS
    );
    assert_eq!(
        handoff_gate.next_missing_stable_promotion_class,
        SHARED_STATE_API_HANDOFF_NEXT_CLASS
    );
    assert_eq!(handoff_gate.evidence_sources.len(), 2);
    let go_source = handoff_gate
        .evidence_sources
        .iter()
        .find(|source| source.target == "go")
        .expect("Go state API handoff source should be checked");
    let current_plus_sources = go_tokenizer_generator_report_ingestion_sources(include_str!(
        "fixtures/go_syntax_corpus/training-report-ingestion-current-plus-v1.json"
    ))
    .expect("current-plus Go report-ingestion manifest should validate");
    assert_eq!(go_source.source_record_count, current_plus_sources.len());
    assert_eq!(
        go_source.state_case_count,
        go_source.source_record_count * 6
    );
    assert_eq!(
        go_source.transition_case_count,
        go_source.source_record_count * 4
    );
    assert_eq!(
        go_source.strict_decode_case_count,
        go_source.source_record_count * 4
    );
    for source in current_plus_sources {
        assert!(
            go_source.supported_record_ids.contains(&source.source_path),
            "Go state API handoff source should include manifest source {}",
            source.source_path
        );
    }

    let csharp_source = handoff_gate
        .evidence_sources
        .iter()
        .find(|source| source.target == "csharp")
        .expect("C# state API handoff source should be checked");
    assert_eq!(csharp_source.source_record_count, 5);
    assert_eq!(
        csharp_source
            .source_record_raw_token_emission_api_id
            .as_deref(),
        Some(CSHARP_SOURCE_RECORD_RAW_TOKEN_EMISSION_API_ID)
    );
    assert_eq!(
        csharp_source
            .source_record_raw_token_emission_api_boundary
            .as_deref(),
        Some(CSHARP_SOURCE_RECORD_RAW_TOKEN_EMISSION_API_BOUNDARY)
    );
    assert_eq!(csharp_source.state_case_count, 25);
    assert_eq!(csharp_source.transition_case_count, 20);
    assert!(
        csharp_source
            .supported_record_ids
            .iter()
            .any(|record| record == "serialization/Loan.cs")
    );
    assert!(
        go_source
            .supported_record_ids
            .iter()
            .any(|record| record == "tests/fixtures/go_syntax_corpus/src/internal/dag/parse.go")
    );

    assert_eq!(
        handoff_gate.target_neutral_surface.bpe_raw_expansion_policy,
        SHARED_STATE_API_BPE_RAW_EXPANSION_POLICY
    );
    assert!(
        !handoff_gate
            .target_neutral_surface
            .bpe_layer_defines_validity
    );
    assert!(!handoff_gate.claim_boundary.tct_compiler_routing_used);
    assert!(
        !handoff_gate
            .claim_boundary
            .grammar_ir_or_structural_model_routed_through_tct_compiler
    );
    assert!(!handoff_gate.claim_boundary.arena_ir_proof_used);
    assert!(
        handoff_gate
            .validation_commands
            .iter()
            .any(|command| command.contains("syntax_state_machine_replay_test"))
    );
}

