#[test]
fn syntax_backend_source_program_handoff_consumes_csharp_generated_codec_completion_handoff() {
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let csharp_corpus_gate = load_csharp_real_source_generated_codec_corpus_gate();
    let csharp_completion_handoff_gate =
        load_csharp_real_source_generated_codec_completion_handoff_gate();
    let handoff_gate = load_source_program_handoff_gate();

    csharp_completion_handoff_gate
        .validate_against_corpus(&csharp_corpus_gate, &source_corpus_gate)
        .expect("C# completion handoff should be valid before source-program handoff");
    handoff_gate
        .validate_against_csharp_generated_codec_completion_handoff(&csharp_completion_handoff_gate)
        .expect("source-program handoff should consume C# completion handoff evidence");

    assert_eq!(
        handoff_gate
            .csharp_generated_codec_completion_handoff
            .supported_record_count,
        5
    );
    assert_eq!(
        handoff_gate
            .csharp_generated_codec_completion_handoff
            .blocked_record_count,
        0
    );
    assert!(
        handoff_gate
            .csharp_generated_codec_completion_handoff
            .supported_manifest_paths
            .iter()
            .any(|path| path == "serialization/Loan.cs")
    );
    assert!(
        handoff_gate
            .csharp_generated_codec_completion_handoff
            .generated_codec_report_paths
            .iter()
            .any(|path| path
                == "target/tct-syntax-real-source-demo/csharp-loan-generated-codec-demo.json")
    );
    assert!(
        !handoff_gate
            .csharp_generated_codec_completion_handoff
            .source_program_claim_allowed
    );
    assert!(
        !handoff_gate
            .csharp_generated_codec_completion_handoff
            .type_correctness_claim_allowed
    );
    assert!(
        !handoff_gate
            .csharp_generated_codec_completion_handoff
            .arena_ir_proof_used
    );
    assert!(
        handoff_gate
            .claim_profile
            .required_evidence
            .iter()
            .any(|evidence| evidence == "csharp_real_source_generated_codec_completion_handoff")
    );
    assert!(
        handoff_gate
            .claim_profile
            .allowed_claims
            .iter()
            .any(|claim| claim
                == "generated_codec_validity_for_supported_csharp_real_source_records")
    );
}

#[test]
fn syntax_backend_source_program_handoff_rejects_stale_stable_metadata_source_handoff_source_handoff_source_handoff_source_input()
 {
    let route_gate = load_production_route_implementation_gate();
    let route_manifest = load_production_route_manifest();
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let mut stable_metadata_gate = load_stable_metadata_promotion_gate();
    let completion_handoff_gate = load_go_real_source_generated_codec_completion_handoff_gate();
    let handoff_gate = load_source_program_handoff_gate();
    stable_metadata_gate
        .source_completion_handoff
        .source_program_typecheck_execution_report_path =
        "target/stale-stable-metadata-typecheck-execution-report.json".to_string();

    let error = handoff_gate
        .validate_against_promotion_inputs(
            &route_gate,
            &route_manifest,
            &source_corpus_gate,
            &stable_metadata_gate,
            &completion_handoff_gate,
        )
        .expect_err("source-program handoff must reject stale stable metadata source counts");

    assert_eq!(
        error.field(),
        "stable_metadata_promotion.source_fixture_source_completion_handoff_source_program_typecheck_execution_report_path"
    );
}

