#[test]
fn syntax_backend_source_program_handoff_report_matches_source_corpus_report() {
    let route_gate = load_production_route_implementation_gate();
    let route_manifest = load_production_route_manifest();
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let handoff_gate = load_source_program_handoff_gate();
    let source_corpus_report = source_corpus_gate
        .build_report(&route_gate, &route_manifest)
        .expect("source-corpus report should build for handoff producer");

    let report = handoff_gate
        .build_report(
            &route_gate,
            &route_manifest,
            &source_corpus_gate,
            SOURCE_CORPUS_EVIDENCE_REPORT_PATH,
            &source_corpus_report,
        )
        .expect("source-program handoff report should build from source-corpus report");

    handoff_gate
        .validate_report(&report)
        .expect("source-program handoff report should validate against checked profile");

    assert_eq!(
        report.artifact_kind,
        SOURCE_PROGRAM_HANDOFF_REPORT_ARTIFACT_KIND
    );
    assert_eq!(report.status, SOURCE_PROGRAM_HANDOFF_REPORT_STATUS);
    assert_eq!(report.profile_id, SOURCE_PROGRAM_HANDOFF_PROFILE_ID);
    assert_eq!(report.record_count, source_corpus_report.record_count);
    assert_eq!(
        report.stable_metadata_promotion.completed_promotion_class,
        STABLE_METADATA_PROMOTION_IMPLEMENTATION_COMPLETED_CLASS
    );
    assert_eq!(
        report
            .go_generated_codec_completion_handoff
            .completed_promotion_class,
        GO_REAL_SOURCE_GENERATED_CODEC_COMPLETION_HANDOFF_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        report.source_corpus.records_sha256,
        source_corpus_report.records_sha256
    );
    assert_eq!(
        report.source_corpus.csharp_no_gap_metadata_report,
        source_corpus_report.csharp_no_gap_metadata_report
    );
    assert_eq!(
        report
            .source_corpus
            .csharp_no_gap_metadata_report
            .expected_unsupported_gap_count,
        0
    );
    assert_eq!(
        report.completed_promotion_class,
        SOURCE_PROGRAM_HANDOFF_REPORT_PRODUCER_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        report.next_missing_stable_promotion_class,
        SOURCE_PROGRAM_HANDOFF_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
    let first = report
        .records
        .first()
        .expect("handoff report should preserve parser-backed records");
    assert!(!first.structural_model_sha256.is_empty());
    assert!(!first.route_metadata.generated_json_schema_output_changed);
    assert!(!first.route_metadata.core_compiler_path_changed);
    assert_eq!(
        first.sidecar_controls["arena_ir_proof_used"],
        serde_json::Value::Bool(false)
    );
    assert_eq!(
        first.sidecar_controls["external_sidecars_promoted"],
        serde_json::Value::Bool(false)
    );
}

#[test]
fn syntax_backend_source_program_handoff_report_rejects_stale_record_count() {
    let route_gate = load_production_route_implementation_gate();
    let route_manifest = load_production_route_manifest();
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let handoff_gate = load_source_program_handoff_gate();
    let source_corpus_report = source_corpus_gate
        .build_report(&route_gate, &route_manifest)
        .expect("source-corpus report should build for handoff producer");
    let mut report: SyntaxSourceProgramHandoffReport = handoff_gate
        .build_report(
            &route_gate,
            &route_manifest,
            &source_corpus_gate,
            SOURCE_CORPUS_EVIDENCE_REPORT_PATH,
            &source_corpus_report,
        )
        .expect("source-program handoff report should build");
    report.record_count -= 1;

    let error = handoff_gate
        .validate_report(&report)
        .expect_err("stale source-program handoff reports must fail validation");

    assert_eq!(error.field(), "report.record_count");
}

