#[test]
fn syntax_backend_source_program_external_validation_execution_report_matches_controls() {
    let route_gate = load_production_route_implementation_gate();
    let route_manifest = load_production_route_manifest();
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let handoff_gate = load_source_program_handoff_gate();
    let external_validation_gate = load_source_program_external_validation_gate();
    let source_corpus_report = source_corpus_gate
        .build_report(&route_gate, &route_manifest)
        .expect("source-corpus report should build for external validation execution");
    let handoff_report = handoff_gate
        .build_report(
            &route_gate,
            &route_manifest,
            &source_corpus_gate,
            SOURCE_CORPUS_EVIDENCE_REPORT_PATH,
            &source_corpus_report,
        )
        .expect("source-program handoff report should build");

    let report = external_validation_gate
        .build_execution_report(
            &handoff_gate,
            SOURCE_PROGRAM_EXTERNAL_VALIDATION_FIXTURE_PATH,
            SOURCE_PROGRAM_HANDOFF_REPORT_PATH,
            &handoff_report,
            source_program_external_validation_tool_envelope(),
        )
        .expect("external validation execution report should build");

    external_validation_gate
        .validate_execution_report(&handoff_gate, &handoff_report, &report)
        .expect("external validation execution report should validate");

    assert_eq!(
        report.artifact_kind,
        SOURCE_PROGRAM_EXTERNAL_VALIDATION_EXECUTION_REPORT_ARTIFACT_KIND
    );
    assert_eq!(
        report.tool,
        SOURCE_PROGRAM_EXTERNAL_VALIDATION_EXECUTION_REPORT_TOOL
    );
    assert_eq!(
        report.status,
        SOURCE_PROGRAM_EXTERNAL_VALIDATION_EXECUTION_REPORT_STATUS
    );
    assert_eq!(
        report.audit_coverage.execution_report_path,
        SOURCE_PROGRAM_EXTERNAL_VALIDATION_EXECUTION_REPORT_PATH
    );
    assert_eq!(report.record_count, handoff_report.record_count);
    assert_eq!(
        report.completed_promotion_class,
        SOURCE_PROGRAM_EXTERNAL_VALIDATION_EXECUTION_REPORT_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        report.next_missing_stable_promotion_class,
        SOURCE_PROGRAM_EXTERNAL_VALIDATION_EXECUTION_REPORT_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
    assert_eq!(
        report
            .source_handoff_report
            .stable_metadata_promotion
            .completed_promotion_class,
        STABLE_METADATA_PROMOTION_IMPLEMENTATION_COMPLETED_CLASS
    );
    assert_eq!(
        report
            .source_handoff_report
            .go_generated_codec_completion_handoff
            .completed_promotion_class,
        GO_REAL_SOURCE_GENERATED_CODEC_COMPLETION_HANDOFF_COMPLETED_PROMOTION_CLASS
    );
    assert_eq!(
        report
            .source_handoff_report
            .csharp_generated_codec_completion_handoff
            .completed_promotion_class,
        CSHARP_REAL_SOURCE_GENERATED_CODEC_COMPLETION_HANDOFF_COMPLETED_CLASS
    );
    assert!(
        report
            .source_handoff_report
            .csharp_generated_codec_completion_handoff
            .supported_manifest_paths
            .iter()
            .any(|path| path == "serialization/Loan.cs")
    );
    assert!(report.control_summary.iter().any(|control| {
        control.control_id == "type_checker"
            && !control.ran
            && control.unavailable_records == report.record_count
            && control
                .unsupported_claims
                .iter()
                .any(|claim| claim == "type_correctness_claim")
    }));
    assert!(
        report
            .records
            .iter()
            .all(|record| record
                .control_results
                .iter()
                .any(|control| control.control_id == "functional_validator"
                    && !control.ran
                    && !control.stable_promotion_allowed))
    );
}

