#[test]
fn syntax_backend_go_real_source_program_validity_corpus_consumes_corpus_manifest_and_preserved_typecheck_inputs()
 {
    let manifest = load_go_syntax_corpus_manifest();
    let corpus_gate = load_go_real_source_program_validity_corpus_gate();
    let corpus_fixture: serde_json::Value =
        serde_json::from_str(GO_REAL_SOURCE_PROGRAM_VALIDITY_CORPUS_GATE)
            .expect("Go real-source corpus fixture should parse as JSON");
    let source_typecheck_preservation = corpus_fixture
        .get("source_typecheck_preservation")
        .and_then(serde_json::Value::as_object)
        .expect("Go corpus fixture should preserve the retired type-checker evidence summary");
    let stable_metadata_promotion = source_typecheck_preservation
        .get("stable_metadata_promotion")
        .and_then(serde_json::Value::as_object)
        .expect("Go corpus fixture should pin stable metadata promotion input");
    let completion_handoff = source_typecheck_preservation
        .get("go_generated_codec_completion_handoff")
        .and_then(serde_json::Value::as_object)
        .expect("Go corpus fixture should pin generated-codec completion handoff input");
    let csharp_completion_handoff = source_typecheck_preservation
        .get("csharp_generated_codec_completion_handoff")
        .and_then(serde_json::Value::as_object)
        .expect("Go corpus fixture should pin C# generated-codec completion handoff input");
    let preserved_stable_fields = source_typecheck_preservation
        .get("preserved_stable_report_fields")
        .and_then(serde_json::Value::as_array)
        .expect("Go corpus fixture should pin preservation stable fields");
    let preserved_report_contract_stable_fields = source_typecheck_preservation
        .get("preserved_report_contract_stable_report_fields")
        .and_then(serde_json::Value::as_array)
        .expect("Go corpus fixture should pin preservation report contract stable fields");
    let preserved_blocked_claims = source_typecheck_preservation
        .get("preserved_required_blocked_claims")
        .and_then(serde_json::Value::as_array)
        .expect("Go corpus fixture should pin preservation blocked claims");
    let preserved_no_stable_claims = source_typecheck_preservation
        .get("preserved_no_stable_claims")
        .and_then(serde_json::Value::as_array)
        .expect("Go corpus fixture should pin preservation no-stable claims");

    corpus_gate
        .validate_against_manifest(&manifest)
        .expect("Go real-source corpus fixture should pin the eligibility boundary");

    assert_eq!(
        corpus_gate.artifact_kind,
        GO_REAL_SOURCE_PROGRAM_VALIDITY_CORPUS_ARTIFACT_KIND
    );
    assert_eq!(
        GO_REAL_SOURCE_PROGRAM_VALIDITY_CORPUS_FIXTURE_PATH,
        "tests/fixtures/syntax_backend/go-real-source-program-validity-corpus-v1.json"
    );
    assert_eq!(
        corpus_gate.next_missing_stable_promotion_class,
        GO_REAL_SOURCE_PROGRAM_VALIDITY_CORPUS_NEXT_MISSING_STABLE_PROMOTION_CLASS
    );
    assert_eq!(
        corpus_gate.corpus_check_report_contract.report_path,
        GO_REAL_SOURCE_PROGRAM_VALIDITY_CORPUS_REPORT_PATH
    );
    // The source-program type-checker execution evidence family is retired;
    // the `source_typecheck_preservation` block is preserved historical
    // fixture metadata only. The live preservation gate, the typecheck
    // execution/feasibility reports, and their CLI producers were removed.
    let typecheck_preservation_source = &corpus_gate.source_typecheck_preservation;
    assert_eq!(
        typecheck_preservation_source.fixture_path,
        "tests/fixtures/syntax_backend/source-program-typecheck-execution-preservation-v1.json"
    );
    assert_eq!(
        typecheck_preservation_source.source_typecheck_execution_report_path,
        "target/tct-syntax-source-program-typecheck-execution/execution-report-v1.json"
    );
    assert_eq!(
        typecheck_preservation_source.source_typecheck_feasibility_report_path,
        "target/tct-syntax-source-program-typecheck-feasibility/feasibility-report-v1.json"
    );
    let csharp_handoff = &corpus_gate
        .source_typecheck_preservation
        .csharp_generated_codec_completion_handoff;
    assert_eq!(csharp_handoff.supported_record_count, 5);
    for manifest_path in [
        "pattern-matching/Shapes.cs",
        "delegates-and-events/Logger.cs",
        "events/VersionOne.cs",
        "iterators/IteratorMethods.cs",
        "serialization/Loan.cs",
    ] {
        assert!(
            csharp_handoff
                .supported_manifest_paths
                .iter()
                .any(|path| path == manifest_path)
        );
    }
    assert!(
        csharp_handoff
            .generated_codec_routes
            .iter()
            .any(|route| route == "csharp_compilation_unit_source_file_syntax_v0")
    );
    assert!(
        csharp_handoff
            .generated_codec_markers
            .iter()
            .any(|marker| marker == "generated_csharp_compilation_unit_source_file_round_trips")
    );
    for report_path in [
        "target/tct-syntax-real-source-demo/csharp-shapes-generated-codec-demo.json",
        "target/tct-syntax-real-source-demo/csharp-logger-generated-codec-demo.json",
        "target/tct-syntax-real-source-demo/csharp-version-one-generated-codec-demo.json",
        "target/tct-syntax-real-source-demo/csharp-iterator-methods-generated-codec-demo.json",
        "target/tct-syntax-real-source-demo/csharp-loan-generated-codec-demo.json",
    ] {
        assert!(
            csharp_handoff
                .generated_codec_report_paths
                .iter()
                .any(|path| path == report_path)
        );
    }
    assert!(!csharp_handoff.source_program_claim_allowed);
    assert!(csharp_handoff.whole_file_generated_codec_claim_allowed);
    assert!(!csharp_handoff.type_correctness_claim_allowed);
    assert!(!csharp_handoff.arena_ir_proof_used);
    assert!(!csharp_handoff.generated_json_schema_output_changed);
    assert!(csharp_handoff.json_schema_backend_preserved);
    assert_eq!(
        corpus_gate
            .source_typecheck_preservation
            .preserved_stable_report_fields,
        corpus_gate
            .source_typecheck_preservation
            .stable_metadata_promotion
            .source_completion_handoff_source_program_preserved_typecheck_stable_report_fields
    );
    assert_eq!(
        corpus_gate
            .source_typecheck_preservation
            .preserved_required_blocked_claims,
        corpus_gate
            .source_typecheck_preservation
            .stable_metadata_promotion
            .source_completion_handoff_source_program_preserved_typecheck_blocked_claims
    );
    assert_eq!(
        corpus_gate
            .source_typecheck_preservation
            .execution_pass_envelope_required_record_count,
        84
    );
    assert!(
        corpus_gate
            .source_typecheck_preservation
            .execution_pass_envelope_required_record_ids
            .iter()
            .any(|record_id| record_id == "go_local_call_return_expression_syntax_v0")
    );
    assert!(
        corpus_gate
            .source_typecheck_preservation
            .execution_pass_envelope_required_record_ids
            .iter()
            .any(|record_id| record_id == "go_local_argument_call_return_expression_syntax_v0")
    );
    assert!(
        corpus_gate
            .source_typecheck_preservation
            .execution_pass_envelope_required_record_ids
            .iter()
            .any(|record_id| record_id == "csharp_local_nullable_return_type_syntax_v0")
    );
    assert!(
        corpus_gate
            .source_typecheck_preservation
            .execution_pass_envelope_required_record_ids
            .iter()
            .any(|record_id| record_id == "csharp_local_nullable_declaration_syntax_v0")
    );
    assert!(
        corpus_gate
            .source_typecheck_preservation
            .execution_pass_envelope_required_record_ids
            .iter()
            .any(|record_id| record_id == "csharp_nullable_property_declaration_syntax_v0")
    );
    assert!(
        corpus_gate
            .source_typecheck_preservation
            .execution_pass_envelope_required_record_ids
            .iter()
            .any(|record_id| record_id == "csharp_nullable_parameter_declaration_syntax_v0")
    );
    assert!(
        corpus_gate
            .source_typecheck_preservation
            .execution_evidence_typechecker_results_sidecar_only
    );
    assert!(
        !corpus_gate
            .source_typecheck_preservation
            .execution_evidence_type_correctness_claim_allowed
    );
    assert!(
        !corpus_gate
            .source_typecheck_preservation
            .execution_evidence_arena_ir_proof_used
    );
    assert!(
        corpus_gate
            .source_typecheck_preservation
            .execution_evidence_json_schema_backend_unchanged
    );
    assert_eq!(
        stable_metadata_promotion
            .get("source_completion_handoff_supported_record_count")
            .and_then(serde_json::Value::as_u64),
        Some(7)
    );
    assert_eq!(
        stable_metadata_promotion
            .get("source_completion_handoff_blocked_record_count")
            .and_then(serde_json::Value::as_u64),
        Some(0)
    );
    assert!(
        stable_metadata_promotion
            .get("source_completion_handoff_supported_manifest_paths")
            .and_then(serde_json::Value::as_array)
            .expect("Go corpus fixture should pin supported source manifest paths")
            .iter()
            .any(|path| path.as_str() == Some("strings/compare.go"))
    );
    assert!(
        stable_metadata_promotion
            .get("source_completion_handoff_generated_codec_routes")
            .and_then(serde_json::Value::as_array)
            .expect("Go corpus fixture should pin generated-codec routes")
            .iter()
            .any(|route| route.as_str() == Some("go_strings_compare_source_file_syntax_v0"))
    );
    assert!(
        stable_metadata_promotion
            .get("source_completion_handoff_generated_codec_markers")
            .and_then(serde_json::Value::as_array)
            .expect("Go corpus fixture should pin generated-codec markers")
            .iter()
            .any(|marker| {
                marker.as_str() == Some("generated_go_strings_compare_source_file_round_trips")
            })
    );
    assert_eq!(
        completion_handoff
            .get("supported_record_count")
            .and_then(serde_json::Value::as_u64),
        Some(7)
    );
    assert_eq!(
        completion_handoff
            .get("blocked_record_count")
            .and_then(serde_json::Value::as_u64),
        Some(0)
    );
    assert_eq!(
        csharp_completion_handoff
            .get("supported_record_count")
            .and_then(serde_json::Value::as_u64),
        Some(5)
    );
    assert!(
        csharp_completion_handoff
            .get("supported_manifest_paths")
            .and_then(serde_json::Value::as_array)
            .expect("Go corpus fixture should pin C# supported source paths")
            .iter()
            .any(|path| path.as_str() == Some("serialization/Loan.cs"))
    );
    assert!(
        csharp_completion_handoff
            .get("generated_codec_report_paths")
            .and_then(serde_json::Value::as_array)
            .expect("Go corpus fixture should pin C# generated-codec reports")
            .iter()
            .any(|path| {
                path.as_str()
                    == Some(
                        "target/tct-syntax-real-source-demo/csharp-loan-generated-codec-demo.json",
                    )
            })
    );
    assert!(
        preserved_stable_fields
            .iter()
            .any(|field| field.as_str()
                == Some("source_feasibility_report.stable_metadata_promotion"))
    );
    assert!(preserved_stable_fields.iter().any(|field| field.as_str()
        == Some("source_feasibility_report.go_generated_codec_completion_handoff")));
    assert!(
        preserved_report_contract_stable_fields
            .iter()
            .any(|field| field.as_str()
                == Some("source_feasibility_report.stable_metadata_promotion.source_completion_handoff_source_program_preserved_typecheck_report_contract_stable_report_fields"))
    );
    assert!(
        preserved_report_contract_stable_fields
            .iter()
            .any(|field| field.as_str()
                == Some("source_feasibility_report.stable_metadata_promotion.source_completion_handoff_generated_codec_round_trip_records"))
    );
    assert!(
        preserved_report_contract_stable_fields
            .iter()
            .any(|field| field.as_str()
                == Some("source_feasibility_report.stable_metadata_promotion.source_completion_handoff_source_program_typechecker_results_sidecar_only"))
    );
    assert!(
        preserved_report_contract_stable_fields
            .iter()
            .any(|field| field.as_str() == Some("records.generated_hot_path_allowed"))
    );
    assert!(
        preserved_report_contract_stable_fields
            .iter()
            .any(|field| field.as_str() == Some("control_boundary.arena_ir_proof_allowed"))
    );
    assert!(
        preserved_blocked_claims
            .iter()
            .any(|claim| claim.as_str() == Some("source_completion_or_infill_claim"))
    );
    assert!(
        preserved_blocked_claims
            .iter()
            .any(|claim| claim.as_str() == Some("generated_hot_path_claim"))
    );
    assert!(
        preserved_blocked_claims
            .iter()
            .any(|claim| claim.as_str() == Some("arena_ir_promotion"))
    );
    assert!(
        preserved_no_stable_claims
            .iter()
            .any(|claim| claim.as_str() == Some("no_generated_hot_path_typechecker"))
    );
    assert_eq!(
        source_typecheck_preservation
            .get("execution_evidence_typechecker_results_sidecar_only")
            .and_then(serde_json::Value::as_bool),
        Some(true)
    );
    assert_eq!(
        source_typecheck_preservation
            .get("execution_evidence_type_correctness_claim_allowed")
            .and_then(serde_json::Value::as_bool),
        Some(false)
    );
    assert!(
        stable_metadata_promotion
            .get("source_completion_handoff_source_program_no_stable_claims")
            .and_then(serde_json::Value::as_array)
            .expect("Go corpus fixture should pin source-program no-stable claims")
            .iter()
            .any(|claim| claim.as_str() == Some("no_source_program_validity_claim"))
    );
    assert!(
        stable_metadata_promotion
            .get("source_completion_handoff_generated_codec_allowed_claims")
            .and_then(serde_json::Value::as_array)
            .expect("Go corpus fixture should pin generated-codec allowed claims")
            .iter()
            .any(|claim| claim.as_str()
                == Some("whole_file_generated_codec_claim_for_checked_go_real_source_corpus"))
    );
    assert_eq!(corpus_gate.corpus_eligibility.eligible_record_count, 7);
    assert_eq!(corpus_gate.corpus_eligibility.unsupported_record_count, 0);
    assert!(
        corpus_gate
            .corpus_eligibility
            .eligible_records
            .iter()
            .any(|record| record.manifest_path == "strings/compare.go")
    );
    assert!(
        !corpus_gate
            .sidecar_validity_policy
            .source_program_validity_claim_allowed
    );
    assert!(!corpus_gate.sidecar_validity_policy.arena_ir_proof_used);
    assert!(
        corpus_gate
            .sidecar_validity_policy
            .json_schema_backend_unchanged
    );
}

