#[test]
fn syntax_backend_go_real_source_program_validity_corpus_rejects_source_program_claim() {
    let manifest = load_go_syntax_corpus_manifest();
    let mut corpus_gate = load_go_real_source_program_validity_corpus_gate();
    corpus_gate
        .sidecar_validity_policy
        .source_program_validity_claim_allowed = true;

    let error = corpus_gate
        .validate_against_manifest(&manifest)
        .expect_err("Go corpus eligibility must not promote source-program validity claims");

    assert_eq!(
        error.field(),
        "sidecar_validity_policy.source_program_validity_claim_allowed"
    );
}

#[test]
fn syntax_backend_go_real_source_program_validity_corpus_rejects_missing_manifest_record() {
    let mut manifest = load_go_syntax_corpus_manifest();
    let corpus_gate = load_go_real_source_program_validity_corpus_gate();
    manifest
        .entries
        .retain(|entry| entry.manifest_path != "strings/search.go");

    let error = corpus_gate
        .validate_against_manifest(&manifest)
        .expect_err("Go corpus eligibility must match the pinned manifest records");

    assert_eq!(error.field(), "manifest.entries");
}

