#[test]
fn syntax_backend_go_real_source_generated_codec_completion_handoff_rejects_arena_ir_proof() {
    let generated_codec_corpus_gate = load_go_real_source_generated_codec_corpus_gate();
    let final_decision_gate = load_final_promotion_decision_gate();
    let mut completion_handoff_gate = load_go_real_source_generated_codec_completion_handoff_gate();
    completion_handoff_gate.claim_boundary.arena_ir_proof_used = true;

    let error = completion_handoff_gate
        .validate_against_corpus(&generated_codec_corpus_gate, &final_decision_gate)
        .expect_err("completion handoff must not use arena IR as syntax-level proof");

    assert_eq!(error.field(), "claim_boundary.arena_ir_proof_used");
}

