#[test]
fn syntax_backend_source_program_external_validation_rejects_promoted_external_policy() {
    let route_gate = load_production_route_implementation_gate();
    let route_manifest = load_production_route_manifest();
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let handoff_gate = load_source_program_handoff_gate();
    let external_validation_gate = load_source_program_external_validation_gate();
    let source_corpus_report = source_corpus_gate
        .build_report(&route_gate, &route_manifest)
        .expect("source-corpus report should build for external validation handoff");
    let mut handoff_report = handoff_gate
        .build_report(
            &route_gate,
            &route_manifest,
            &source_corpus_gate,
            SOURCE_CORPUS_EVIDENCE_REPORT_PATH,
            &source_corpus_report,
        )
        .expect("source-program handoff report should build");
    handoff_report.records[0].validation_hook_status["external_check_policy"]["policy"]["stable_gate_promoted"] =
        serde_json::Value::Bool(true);
    handoff_report.records_sha256 =
        json_sha256(&handoff_report.records).expect("mutated records should hash");

    let error = external_validation_gate
        .validate_against_handoff(&handoff_gate, &handoff_report)
        .expect_err("external validation controls must reject promoted sidecar policy");

    assert_eq!(
        error.field(),
        "record.validation_hook_status.external_check_policy.policy.stable_gate_promoted"
    );
}

#[test]
fn syntax_backend_source_program_external_validation_rejects_missing_type_checker_blocker() {
    let route_gate = load_production_route_implementation_gate();
    let route_manifest = load_production_route_manifest();
    let source_corpus_gate = load_source_corpus_evidence_gate();
    let handoff_gate = load_source_program_handoff_gate();
    let mut external_validation_gate = load_source_program_external_validation_gate();
    let source_corpus_report = source_corpus_gate
        .build_report(&route_gate, &route_manifest)
        .expect("source-corpus report should build for external validation handoff");
    let handoff_report = handoff_gate
        .build_report(
            &route_gate,
            &route_manifest,
            &source_corpus_gate,
            SOURCE_CORPUS_EVIDENCE_REPORT_PATH,
            &source_corpus_report,
        )
        .expect("source-program handoff report should build");
    let type_checker = external_validation_gate
        .required_controls
        .iter_mut()
        .find(|control| control.control_id == "type_checker")
        .expect("external validation fixture should track type-checker controls");
    type_checker.blocker.clear();

    let error = external_validation_gate
        .validate_against_handoff(&handoff_gate, &handoff_report)
        .expect_err("missing type-checker controls need a precise blocker");

    assert_eq!(error.field(), "required_controls.blocker");
}

