const GO_TOKEN_LAYOUT_PIN_ARTIFACT_KIND: &str = "tct_go_syntax_token_layout_pin";
const GO_TOKEN_LAYOUT_PIN_PREVIOUS_NOTE: &str = "Pre-pinning 577-era layouts assigned alternative node_start tokens alphabetically per sidecar, so per-record token maps could disagree with the full-inventory map (for example CallExpr was 14 in the strings_reader per-record grammar but 16 globally). The alternative table recorded here is the full-inventory assignment, which the pinned table preserves unchanged.";

const CSHARP_TOKEN_LAYOUT_PIN_ARTIFACT_KIND: &str = "tct_csharp_syntax_token_layout_pin";
const CSHARP_TOKEN_LAYOUT_PIN_NOTE: &str = "Absolute pin of csharp_syntax_token_layout ranges, pad, vocab, and fixed role offsets. C# stays on the expanded stream contract (raw-syntax-stream-expanded-v1); Go canonical streams use elided-v1 — do not confuse the two. This is a token-layout pin, not a tree-sitter grammar pin: TODO.md \"No new pin\" forbids new tree-sitter language/grammar pins, not locking the C# structural layout against silent renumber. Alternative node_start IDs remain alphabetical per C# grammar sidecar (no global inventory table like Go). Updating this fixture is a tct-token-diff breaking_change for downstream raw-token corpora and BPE artifacts and must not be done merely to make a refactor pass.";

fn go_token_layout_pin_role_offsets() -> BTreeMap<String, u32> {
    BTreeMap::from([
        ("node_start".to_string(), RAW_NODE_START_OFFSET),
        ("node_end".to_string(), RAW_NODE_END_OFFSET),
        ("field_start".to_string(), RAW_FIELD_START_OFFSET),
        ("field_end".to_string(), RAW_FIELD_END_OFFSET),
        ("field_missing".to_string(), RAW_FIELD_MISSING_OFFSET),
        ("repeated_empty".to_string(), RAW_REPEATED_EMPTY_OFFSET),
        ("terminal".to_string(), RAW_TERMINAL_OFFSET),
        ("payload_end".to_string(), RAW_PAYLOAD_END_OFFSET),
        ("boolean_false".to_string(), RAW_BOOLEAN_FALSE_OFFSET),
        ("boolean_true".to_string(), RAW_BOOLEAN_TRUE_OFFSET),
    ])
}

fn go_token_layout_pin_alternative_tokens(structural_start: u32) -> BTreeMap<String, u32> {
    go_pinned_alternative_node_start_tokens()
        .expect("pinned Go alternative node_start table should load from the checked inventory")
        .iter()
        .map(|(node_kind, token_id)| (node_kind.clone(), structural_start + *token_id))
        .collect()
}

fn go_token_layout_pin_descriptor_from_layout(
    layout_id: &str,
    layout_version: u32,
    layout: &GrammarStructuralTokenLayout,
) -> SyntaxTokenLayoutDescriptor {
    let structural_start = layout
        .ranges
        .iter()
        .find(|range| range.role == "structural_decisions")
        .expect("Go layout should expose a structural_decisions range")
        .start;
    SyntaxTokenLayoutDescriptor {
        layout_id: layout_id.to_string(),
        layout_version,
        stream_contract: LIVE_RAW_SYNTAX_STREAM_CONTRACT.to_string(),
        vocab_size: layout.vocab_size,
        pad_token: layout.pad_token,
        ranges: layout
            .ranges
            .iter()
            .map(|range| SyntaxTokenLayoutRangeDescriptor {
                id: range.id.clone(),
                role: range.role.clone(),
                start: range.start,
                end_exclusive: range.end_exclusive,
            })
            .collect(),
        role_offsets: go_token_layout_pin_role_offsets(),
        alternative_node_start_tokens: go_token_layout_pin_alternative_tokens(structural_start),
    }
}

fn go_token_layout_pin_current_descriptors()
-> (SyntaxTokenLayoutDescriptor, SyntaxTokenLayoutDescriptor) {
    (
        go_token_layout_pin_descriptor_from_layout(
            "go-syntax-token-layout-v2",
            2,
            &go_syntax_token_layout(),
        ),
        go_token_layout_pin_descriptor_from_layout(
            "go-syntax-source-file-token-layout-v2",
            2,
            &go_syntax_source_file_token_layout(),
        ),
    )
}

fn go_token_layout_pin_previous_descriptor(
    layout_id: &str,
    integer_range_id: &str,
    integer_role: &str,
) -> SyntaxTokenLayoutDescriptor {
    SyntaxTokenLayoutDescriptor {
        layout_id: layout_id.to_string(),
        layout_version: 1,
        // The 577-era previous legs are frozen expanded-era evidence: they
        // stay on the expanded contract even after the live contract flips.
        stream_contract: RAW_SYNTAX_STREAM_CONTRACT_EXPANDED_V1.to_string(),
        vocab_size: 577,
        pad_token: 576,
        ranges: vec![
            SyntaxTokenLayoutRangeDescriptor {
                id: "go.structural_tokens".to_string(),
                role: "structural_decisions".to_string(),
                start: 0,
                end_exclusive: 64,
            },
            SyntaxTokenLayoutRangeDescriptor {
                id: "go.utf8_byte_payload".to_string(),
                role: "utf8_byte_payload".to_string(),
                start: 64,
                end_exclusive: 320,
            },
            SyntaxTokenLayoutRangeDescriptor {
                id: integer_range_id.to_string(),
                role: integer_role.to_string(),
                start: 320,
                end_exclusive: 576,
            },
        ],
        role_offsets: go_token_layout_pin_role_offsets(),
        alternative_node_start_tokens: go_token_layout_pin_alternative_tokens(0),
    }
}

fn go_token_layout_pin_previous_descriptors()
-> (SyntaxTokenLayoutDescriptor, SyntaxTokenLayoutDescriptor) {
    (
        go_token_layout_pin_previous_descriptor(
            "go-syntax-token-layout-v1",
            "go.u8_integer_payload",
            "u8_integer_payload",
        ),
        go_token_layout_pin_previous_descriptor(
            "go-syntax-source-file-token-layout-v1",
            "go.integer_lexeme_payload",
            "integer_lexeme_payload",
        ),
    )
}

const GO_TOKEN_LAYOUT_PIN_PREVIOUS_CONTRACT_NOTE: &str = "Pre-elision 641 layouts carried the expanded stream contract: every mask-forced token was represented in canonical encoded streams. The deliberate elision break flipped the live contract to elided-v1 with zero moved token ranges; expanded-era raw-token corpora and BPE artifacts are not interchangeable with elided streams.";

/// The immediately-prior contract state: the live 641 layouts frozen on the
/// expanded stream contract (the state before the deliberate elision break).
fn go_token_layout_pin_previous_contract_descriptors()
-> (SyntaxTokenLayoutDescriptor, SyntaxTokenLayoutDescriptor) {
    let (mut token_layout, mut source_file_layout) = go_token_layout_pin_current_descriptors();
    token_layout.stream_contract = RAW_SYNTAX_STREAM_CONTRACT_EXPANDED_V1.to_string();
    source_file_layout.stream_contract = RAW_SYNTAX_STREAM_CONTRACT_EXPANDED_V1.to_string();
    (token_layout, source_file_layout)
}

#[test]
fn go_token_layout_pin_fixture_matches_live_layouts_and_breaking_transition() {
    let fixture: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(GO_TOKEN_LAYOUT_PIN_FIXTURE_PATH)
            .expect("checked Go token-layout pin fixture should be readable"),
    )
    .expect("checked Go token-layout pin fixture should be JSON");
    assert_eq!(fixture["artifact_kind"], GO_TOKEN_LAYOUT_PIN_ARTIFACT_KIND);
    assert_eq!(fixture["version"], 1);

    let (current_token_layout, current_source_file_layout) =
        go_token_layout_pin_current_descriptors();
    let fixture_current_token_layout: SyntaxTokenLayoutDescriptor =
        serde_json::from_value(fixture["current"]["token_layout"].clone())
            .expect("pin fixture current token_layout should deserialize");
    let fixture_current_source_file_layout: SyntaxTokenLayoutDescriptor =
        serde_json::from_value(fixture["current"]["source_file_token_layout"].clone())
            .expect("pin fixture current source_file_token_layout should deserialize");
    assert_eq!(
        fixture_current_token_layout, current_token_layout,
        "checked pin fixture current token_layout must equal the live Go layout; regenerate via `cargo test --test syntax_backend_boundary_test regenerate_go_token_layout_pin_fixture -- --ignored` only for a deliberate layout break"
    );
    assert_eq!(
        fixture_current_source_file_layout, current_source_file_layout,
        "checked pin fixture current source_file_token_layout must equal the live Go source-file layout"
    );
    for current in [
        &fixture_current_token_layout,
        &fixture_current_source_file_layout,
    ] {
        assert_eq!(
            current.stream_contract, LIVE_RAW_SYNTAX_STREAM_CONTRACT,
            "pin fixture current legs must carry the live stream contract"
        );
    }

    let note = fixture["previous_layout"]["note"]
        .as_str()
        .expect("pin fixture previous_layout must carry a note");
    assert!(
        note.contains("alphabetically") && note.contains("per-record"),
        "previous-layout note must record the per-record alphabetical inconsistency: {note}"
    );
    let fixture_previous_token_layout: SyntaxTokenLayoutDescriptor =
        serde_json::from_value(fixture["previous_layout"]["token_layout"].clone())
            .expect("pin fixture previous token_layout should deserialize");
    let fixture_previous_source_file_layout: SyntaxTokenLayoutDescriptor =
        serde_json::from_value(fixture["previous_layout"]["source_file_token_layout"].clone())
            .expect("pin fixture previous source_file_token_layout should deserialize");
    for previous in [
        &fixture_previous_token_layout,
        &fixture_previous_source_file_layout,
    ] {
        assert_eq!(
            previous.stream_contract, RAW_SYNTAX_STREAM_CONTRACT_EXPANDED_V1,
            "pin fixture previous legs are frozen expanded-era evidence"
        );
    }

    for (previous, current, key) in [
        (
            &fixture_previous_token_layout,
            &current_token_layout,
            "token_layout",
        ),
        (
            &fixture_previous_source_file_layout,
            &current_source_file_layout,
            "source_file_token_layout",
        ),
    ] {
        let diff = diff_syntax_token_layouts(previous, current)
            .expect("layout diff should build from pin fixture descriptors");
        assert_eq!(
            diff.compatibility,
            SyntaxLayoutCompatibility::BreakingChange,
            "the 577 -> 641 widening must classify as breaking_change for {key}"
        );
        let diff_value = serde_json::to_value(&diff).expect("layout diff should serialize");
        assert_eq!(
            diff_value, fixture["transition"][key],
            "checked transition for {key} must equal the recomputed layout diff"
        );
        assert_eq!(
            fixture["transition"][key]["compatibility"],
            "breaking_change"
        );
    }

    // Stream-contract flip leg: 641-expanded -> 641-elided is a
    // breaking_change with zero moved token ranges.
    let contract_note = fixture["previous_contract"]["note"]
        .as_str()
        .expect("pin fixture previous_contract must carry a note");
    assert!(
        contract_note.contains("elision") && contract_note.contains("expanded"),
        "previous-contract note must record the deliberate elision break: {contract_note}"
    );
    let (expanded_token_layout, expanded_source_file_layout) =
        go_token_layout_pin_previous_contract_descriptors();
    for (previous, current, key) in [
        (
            &expanded_token_layout,
            &current_token_layout,
            "token_layout",
        ),
        (
            &expanded_source_file_layout,
            &current_source_file_layout,
            "source_file_token_layout",
        ),
    ] {
        let fixture_previous: SyntaxTokenLayoutDescriptor =
            serde_json::from_value(fixture["previous_contract"][key].clone())
                .expect("pin fixture previous_contract leg should deserialize");
        assert_eq!(
            &fixture_previous, previous,
            "pin fixture previous_contract {key} must equal the live layout frozen on the expanded contract"
        );
        let diff = diff_syntax_token_layouts(previous, current)
            .expect("contract-flip diff should build from pin fixture descriptors");
        assert_eq!(
            diff.compatibility,
            SyntaxLayoutCompatibility::BreakingChange,
            "the expanded -> elided contract flip must classify as breaking_change for {key}"
        );
        let diff_value = serde_json::to_value(&diff).expect("contract-flip diff should serialize");
        assert_eq!(
            diff_value["moved_ranges"].as_array().map(Vec::len),
            Some(0),
            "the contract flip must move zero token ranges for {key}"
        );
        assert_eq!(
            diff_value["stream_contract_change"],
            serde_json::json!([
                RAW_SYNTAX_STREAM_CONTRACT_EXPANDED_V1,
                LIVE_RAW_SYNTAX_STREAM_CONTRACT
            ]),
        );
        assert_eq!(
            diff_value, fixture["stream_contract_transition"][key],
            "checked stream-contract transition for {key} must equal the recomputed diff"
        );
    }
}

/// Regenerate the checked Go token-layout pin fixture from the live layouts,
/// the embedded pinned alternative node_start table, and the recorded
/// 577-era previous descriptors. Run only as part of a deliberate layout
/// break: `cargo test --test syntax_backend_boundary_test
/// regenerate_go_token_layout_pin_fixture -- --ignored`.
#[test]
#[ignore = "fixture regenerator: overwrites the checked Go token-layout pin fixture; run manually only for a deliberate layout break"]
fn regenerate_go_token_layout_pin_fixture() {
    let (current_token_layout, current_source_file_layout) =
        go_token_layout_pin_current_descriptors();
    let (previous_token_layout, previous_source_file_layout) =
        go_token_layout_pin_previous_descriptors();
    let (expanded_token_layout, expanded_source_file_layout) =
        go_token_layout_pin_previous_contract_descriptors();
    let token_layout_diff =
        diff_syntax_token_layouts(&previous_token_layout, &current_token_layout)
            .expect("token_layout diff should build");
    let source_file_layout_diff =
        diff_syntax_token_layouts(&previous_source_file_layout, &current_source_file_layout)
            .expect("source_file_token_layout diff should build");
    let contract_token_layout_diff =
        diff_syntax_token_layouts(&expanded_token_layout, &current_token_layout)
            .expect("contract-flip token_layout diff should build");
    let contract_source_file_layout_diff =
        diff_syntax_token_layouts(&expanded_source_file_layout, &current_source_file_layout)
            .expect("contract-flip source_file_token_layout diff should build");
    let fixture = json!({
        "artifact_kind": GO_TOKEN_LAYOUT_PIN_ARTIFACT_KIND,
        "version": 1,
        "current": {
            "token_layout": current_token_layout,
            "source_file_token_layout": current_source_file_layout,
        },
        "previous_layout": {
            "note": GO_TOKEN_LAYOUT_PIN_PREVIOUS_NOTE,
            "token_layout": previous_token_layout,
            "source_file_token_layout": previous_source_file_layout,
        },
        "transition": {
            "token_layout": token_layout_diff,
            "source_file_token_layout": source_file_layout_diff,
        },
        "previous_contract": {
            "note": GO_TOKEN_LAYOUT_PIN_PREVIOUS_CONTRACT_NOTE,
            "token_layout": expanded_token_layout,
            "source_file_token_layout": expanded_source_file_layout,
        },
        "stream_contract_transition": {
            "token_layout": contract_token_layout_diff,
            "source_file_token_layout": contract_source_file_layout_diff,
        },
    });
    std::fs::write(
        GO_TOKEN_LAYOUT_PIN_FIXTURE_PATH,
        serde_json::to_string_pretty(&fixture).expect("pin fixture should serialize") + "\n",
    )
    .expect("pin fixture should be written");
}

/// Build the live C# token-layout descriptor from `csharp_syntax_token_layout()`.
/// Numbers always come from the constructor; never hand-edit absolute IDs.
fn csharp_token_layout_pin_current_descriptor() -> SyntaxTokenLayoutDescriptor {
    let layout = csharp_syntax_token_layout();
    SyntaxTokenLayoutDescriptor {
        layout_id: "csharp-syntax-token-layout-v1".to_string(),
        layout_version: 1,
        // C# stays on the expanded contract; do not stamp LIVE (elided) here.
        stream_contract: RAW_SYNTAX_STREAM_CONTRACT_EXPANDED_V1.to_string(),
        vocab_size: layout.vocab_size,
        pad_token: layout.pad_token,
        ranges: layout
            .ranges
            .iter()
            .map(|range| SyntaxTokenLayoutRangeDescriptor {
                id: range.id.clone(),
                role: range.role.clone(),
                start: range.start,
                end_exclusive: range.end_exclusive,
            })
            .collect(),
        // Same ten fixed structural role offsets as the raw state machine / Go pin.
        role_offsets: go_token_layout_pin_role_offsets(),
        // Product layout has no global alternative table; C# multi-alternative
        // node_start IDs are assigned alphabetically per grammar sidecar.
        alternative_node_start_tokens: BTreeMap::new(),
    }
}

/// Absolute renumber protection for the C# product syntax token layout.
///
/// Fails on any change to ranges, pad, vocab, fixed role offsets, or stream
/// contract relative to the checked pin fixture. Updating the fixture is a
/// `tct-token-diff` breaking change for downstream raw-token corpora and BPE
/// artifacts and must not be done merely to make a refactor pass. See
/// DEVELOPMENT.md ("Schema Evolution Reports") for the layout-diff guidance.
///
/// This is a **token-layout pin**, not a tree-sitter grammar pin.
#[test]
fn csharp_token_layout_pin_fixture_matches_live_layout() {
    let fixture: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(CSHARP_TOKEN_LAYOUT_PIN_FIXTURE_PATH)
            .expect("checked C# token-layout pin fixture should be readable"),
    )
    .expect("checked C# token-layout pin fixture should be JSON");
    assert_eq!(
        fixture["artifact_kind"],
        CSHARP_TOKEN_LAYOUT_PIN_ARTIFACT_KIND
    );
    assert_eq!(fixture["version"], 1);

    let note = fixture["note"]
        .as_str()
        .expect("C# token-layout pin fixture must carry a note");
    assert!(
        note.contains("expanded")
            && note.contains("token-layout pin")
            && note.contains("tree-sitter"),
        "pin note must record expanded stream contract and token-layout vs tree-sitter-grammar-pin disambiguation: {note}"
    );

    let live = csharp_token_layout_pin_current_descriptor();
    let fixture_current: SyntaxTokenLayoutDescriptor =
        serde_json::from_value(fixture["current"]["token_layout"].clone())
            .expect("pin fixture current token_layout should deserialize");
    assert_eq!(
        fixture_current, live,
        "checked pin fixture current token_layout must equal the live csharp_syntax_token_layout() descriptor; regenerate via `cargo test --test syntax_backend_boundary_test regenerate_csharp_token_layout_pin_fixture -- --ignored` only for a deliberate layout break. Updating the fixture is a tct-token-diff breaking_change for downstream raw-token corpora and BPE artifacts and must not be done merely to make a refactor pass."
    );
    assert_eq!(
        fixture_current.stream_contract, RAW_SYNTAX_STREAM_CONTRACT_EXPANDED_V1,
        "C# pin must record the expanded stream contract (not Go's elided LIVE contract)"
    );
    assert_ne!(
        fixture_current.stream_contract, LIVE_RAW_SYNTAX_STREAM_CONTRACT,
        "C# pin stream contract must not equal Go's live elided contract"
    );

    // Self-diff must be exact_reuse: any absolute renumber of the live layout
    // would fail the equality above; this locks the shared diff machinery too.
    let self_diff = diff_syntax_token_layouts(&fixture_current, &live)
        .expect("C# layout self-diff should build");
    assert_eq!(
        self_diff.compatibility,
        SyntaxLayoutCompatibility::ExactReuse,
        "live C# layout vs pin fixture must classify as exact_reuse"
    );
    assert!(self_diff.reasons.is_empty());

    // Perturbation-class check without mutating the fixture: a range move
    // against the pin must classify as breaking_change through the shared
    // layout-diff gate (same machinery Go uses).
    let mut renumbered = live.clone();
    renumbered.ranges[0].end_exclusive = renumbered.ranges[0]
        .end_exclusive
        .checked_add(1)
        .expect("structural end should not overflow");
    let breaking = diff_syntax_token_layouts(&fixture_current, &renumbered)
        .expect("renumbered C# layout diff should build");
    assert_eq!(
        breaking.compatibility,
        SyntaxLayoutCompatibility::BreakingChange,
        "absolute structural renumber against the C# pin must be breaking_change"
    );
    assert!(
        breaking
            .moved_ranges
            .iter()
            .any(|role| role == "structural_decisions"),
        "breaking renumber must report moved structural_decisions: {:?}",
        breaking.moved_ranges
    );
}

/// Regenerate the checked C# token-layout pin fixture from
/// `csharp_syntax_token_layout()`. Run only as part of a deliberate layout
/// break: `cargo test --test syntax_backend_boundary_test
/// regenerate_csharp_token_layout_pin_fixture -- --ignored`.
/// Updating this fixture is a `tct-token-diff` breaking change for downstream
/// raw-token corpora and BPE artifacts.
#[test]
#[ignore = "fixture regenerator: overwrites the checked C# token-layout pin fixture; run manually only for a deliberate layout break"]
fn regenerate_csharp_token_layout_pin_fixture() {
    let current = csharp_token_layout_pin_current_descriptor();
    let fixture = json!({
        "artifact_kind": CSHARP_TOKEN_LAYOUT_PIN_ARTIFACT_KIND,
        "version": 1,
        "note": CSHARP_TOKEN_LAYOUT_PIN_NOTE,
        "current": {
            "token_layout": current,
        },
    });
    std::fs::write(
        CSHARP_TOKEN_LAYOUT_PIN_FIXTURE_PATH,
        serde_json::to_string_pretty(&fixture).expect("C# pin fixture should serialize") + "\n",
    )
    .expect("C# pin fixture should be written");
}

const GO_GRAMMAR_ARTIFACT_PIN_NOTES: &[&str] = &[
    "One pinned inventory-derived artifact id covers the Go raw-token contract: the checked go1.24.3 inventory lowered once, the source-file token layout, the pinned alternative node_start table, the structural-model digest, and the generated-codec fixture sha are bound by content_sha256.",
    "Any content_sha256 change is identity-affecting: treat it like a tct-token-diff breaking_change for downstream raw-token corpora and BPE artifacts unless the Go token-layout pin gate separately proves the layout itself unchanged.",
];

#[test]
fn go_grammar_artifact_pin_fixture_matches_live_artifact() {
    let fixture: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(GO_GRAMMAR_ARTIFACT_PIN_FIXTURE_PATH)
            .expect("checked Go grammar-artifact pin fixture should be readable"),
    )
    .expect("checked Go grammar-artifact pin fixture should be JSON");
    assert_eq!(
        fixture["artifact_kind"],
        GO_GRAMMAR_ARTIFACT_PIN_ARTIFACT_KIND
    );
    assert_eq!(fixture["version"], GO_GRAMMAR_ARTIFACT_PIN_VERSION);
    assert_eq!(fixture["artifact_id"], GO_UNIFIED_GRAMMAR_ARTIFACT_ID);

    let artifact = go_unified_grammar_artifact().expect("unified Go grammar artifact should build");
    assert_eq!(artifact.artifact_id, GO_UNIFIED_GRAMMAR_ARTIFACT_ID);

    let fixture_identity: GoUnifiedGrammarArtifactIdentity =
        serde_json::from_value(fixture["identity"].clone())
            .expect("pin fixture identity should deserialize");
    assert_eq!(
        fixture_identity, artifact.identity,
        "checked pin fixture identity must equal the live unified Go grammar artifact identity; regenerate via `cargo test --test syntax_backend_boundary_test regenerate_go_grammar_artifact_pin_fixture -- --ignored` only for a deliberate identity break, and treat the break like a tct-token-diff breaking_change for downstream raw-token corpora and BPE artifacts"
    );

    // The content hash must recompute from the checked fixture identity alone.
    let recomputed_sha = fixture_identity
        .content_sha256()
        .expect("pin fixture identity hash should recompute");
    assert_eq!(
        fixture["content_sha256"].as_str(),
        Some(recomputed_sha.as_str()),
        "checked content_sha256 must equal the hash recomputed from the checked identity"
    );
    assert_eq!(artifact.content_sha256, recomputed_sha);

    // Layout legs must equal the layout-pin gate's current descriptors so the
    // two pins can never drift apart.
    let layout_pin: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(GO_TOKEN_LAYOUT_PIN_FIXTURE_PATH)
            .expect("checked Go token-layout pin fixture should be readable"),
    )
    .expect("checked Go token-layout pin fixture should be JSON");
    assert_eq!(
        serde_json::to_value(&artifact.identity.token_layout)
            .expect("artifact token_layout should serialize"),
        layout_pin["current"]["token_layout"],
        "unified artifact token_layout must equal the layout-pin current descriptor"
    );
    assert_eq!(
        serde_json::to_value(&artifact.identity.source_file_token_layout)
            .expect("artifact source_file_token_layout should serialize"),
        layout_pin["current"]["source_file_token_layout"],
        "unified artifact source_file_token_layout must equal the layout-pin current descriptor"
    );

    // Identity constituents must recompute from the live bundle.
    assert_eq!(
        artifact.identity.grammar_id,
        "go_ast_schema_inventory_go1_24_3"
    );
    assert_eq!(
        artifact.identity.structural_model_id,
        "grammar-ir:go_ast_schema_inventory_go1_24_3:structural-model-v0"
    );
    assert_eq!(
        artifact.identity.structural_model_id,
        artifact.sidecar.structural_model.model_id
    );
    assert_eq!(
        artifact.identity.structural_model_sha256,
        json_sha256(&artifact.sidecar.structural_model)
            .expect("unified structural model should serialize"),
    );
    assert_eq!(
        artifact.identity.codec_fixture_sha256,
        sha256_hex(render_go_syntax_codec_fixture(&artifact.sidecar).as_bytes()),
    );
    let inventory_sha = tct::provenance::file_provenance(&artifact.identity.inventory_fixture_path)
        .expect("checked inventory fixture should hash")
        .sha256;
    assert_eq!(
        artifact.identity.inventory_fixture_sha256, inventory_sha,
        "embedded inventory contents must match the checked fixture on disk"
    );
    assert_eq!(
        artifact.identity.codec_route,
        GO_UNIFIED_GRAMMAR_ARTIFACT_CODEC_ROUTE
    );
    assert_eq!(
        artifact.identity.codec_route,
        tct::syntax_go_source_instance_projection::GENERATED_CODEC_REPORT_ROUTE,
        "the artifact codec route must stay equal to the projection generated-codec route"
    );
    assert_eq!(
        artifact.identity.pinned_alternative_node_start_offsets,
        go_pinned_alternative_node_start_tokens()
            .expect("pinned Go alternative node_start table should load")
            .clone(),
    );
    assert_eq!(
        fixture["notes"],
        serde_json::to_value(GO_GRAMMAR_ARTIFACT_PIN_NOTES)
            .expect("maintained pin notes should serialize"),
        "pin fixture notes must match the maintained note set"
    );
}

/// Regenerate the checked Go grammar-artifact pin fixture from the live
/// unified artifact. Run only as part of a deliberate identity break:
/// `cargo test --test syntax_backend_boundary_test
/// regenerate_go_grammar_artifact_pin_fixture -- --ignored`.
#[test]
#[ignore = "fixture regenerator: overwrites the checked Go grammar-artifact pin fixture; run manually only for a deliberate unified-artifact identity break"]
fn regenerate_go_grammar_artifact_pin_fixture() {
    let artifact = go_unified_grammar_artifact().expect("unified Go grammar artifact should build");
    let fixture = json!({
        "artifact_kind": GO_GRAMMAR_ARTIFACT_PIN_ARTIFACT_KIND,
        "version": GO_GRAMMAR_ARTIFACT_PIN_VERSION,
        "artifact_id": artifact.artifact_id,
        "content_sha256": artifact.content_sha256,
        "identity": artifact.identity,
        "notes": GO_GRAMMAR_ARTIFACT_PIN_NOTES,
    });
    std::fs::write(
        GO_GRAMMAR_ARTIFACT_PIN_FIXTURE_PATH,
        serde_json::to_string_pretty(&fixture).expect("pin fixture should serialize") + "\n",
    )
    .expect("pin fixture should be written");
}
